import React, { useState, useEffect } from 'react';
import { makeStyles } from '@mui/styles';
import Sidebar from './Sidebar.js'
import ShareButtons from './ShareButtons';
import YouTubeLink from './YouTubeLink';
import SearchPlayersDetails from './SearchPlayersDetails.js'
import ExploraPlayers from './cards/ExploraPlayers';
import Card from '@mui/material/Card';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import Typography from '@mui/material/Typography';
import { Box, Grid } from '@mui/material';

const useStyles = makeStyles((theme) => ({
  navCard: {
    borderTop: '4px solid #CA2331',
    marginBottom: theme.spacing(2),
    overflow: 'hidden',
  },
  navHeader: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1.5),
    padding: theme.spacing(1, 2),
    backgroundImage: 'url(https://www.archiviorossoblu.it/images/header-gradient-bg.jpg)',
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    position: 'relative',
    '&::before': {
      content: '""',
      position: 'absolute',
      inset: 0,
      background: 'rgba(8,45,104,0.60)',
    },
    '& > *': {
      position: 'relative',
      zIndex: 1,
    },
  },
  brand: {
    fontWeight: 800,
    fontSize: '1.6rem',
    color: '#F0C040',
    textDecoration: 'none',
    flex: 1,
  },
}));

export default function SearchPlayers() {
  const classes = useStyles();
  const [allPlayers, setAllPlayers] = useState([]);
  const [selectedCountry, setSelectedCountry] = useState('Italia');

  useEffect(() => {
    let isMounted = true;
    fetch('/allPlayers.json')
      .then(r => r.json())
      .then(data => { if (isMounted) setAllPlayers(data); });
    return () => { isMounted = false; };
  }, []);
  const [selectedYear, setSelectedYear] = useState(null);
  const [checkedPeriods, setCheckedPeriods] = useState(null);

  return (
    <div>
      <Card className={classes.navCard}>
        <div className={classes.navHeader}>
          <Sidebar iconColor="#F0C040" />
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, flex: 1 }}>
            <img src="https://www.archiviorossoblu.it/images/sun-gold-sella-bg.png" alt="logo" title="ArchivioRossoBlu" style={{ width: 80, height: 80, flexShrink: 0 }} />
            <Typography component="a" href="/cagliari-calcio" className={classes.brand} style={{ flex: 'none' }}>
              <span className="brand-short" title="ArchivioRossoBlu">ARB</span>
              <span className="brand-full">ArchivioRossoBlu</span>
            </Typography>
          </div>
          <YouTubeLink />
          <ShareButtons />
          <Chip label="Giocatori" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
        </div>
        <Divider />
      </Card>
      <Box p={2}>
        <Grid container spacing={2}>
          <Grid item xs={12} md={4} sx={{ display: 'flex' }}>
            <ExploraPlayers onlyNationality allPlayers={allPlayers} selectedCountry={selectedCountry} onSelectCountry={setSelectedCountry} />
          </Grid>
          <Grid item xs={12} md={4} sx={{ display: 'flex' }}>
            <ExploraPlayers onlyCountryDetail allPlayers={allPlayers} selectedCountry={selectedCountry} onSelectCountry={setSelectedCountry} />
          </Grid>
          <Grid item xs={12} md={4} sx={{ display: 'flex' }}>
            <ExploraPlayers onlyBirthYear allPlayers={allPlayers} selectedCountry={selectedCountry} onSelectCountry={setSelectedCountry} selectedYear={selectedYear} onSelectYear={setSelectedYear} onPeriodsChange={setCheckedPeriods} />
          </Grid>
          <Grid item xs={12}>
            <SearchPlayersDetails allPlayers={allPlayers} countryFilter={selectedCountry} yearFilter={selectedYear} checkedPeriods={checkedPeriods} />
          </Grid>
        </Grid>
      </Box>
    </div>
  );
}
