import React, { useState } from 'react';
import { trackCardClick } from '../../utils/analytics';
import { makeStyles } from '@mui/styles';
import SectionLabel from '../SectionLabel';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import Typography from '@mui/material/Typography';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import Avatar from '@mui/material/Avatar';
import IconButton from '@mui/material/IconButton';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import Moment from 'react-moment';
import PlayerReport from '../dialogs/PlayerReport';
import * as ARBApi from '../../utils/ARBApi';
import Flag from '../Flag';
import { allCountries } from '../../utils/generals';


const useStyles = makeStyles((theme) => ({
  root: {
    borderTop: '4px solid #CA2331',
    height: '100%',
    display: 'flex',
    flexDirection: 'column',
  },
  content: {
    flex: 1,
    overflowY: 'auto',
    maxHeight: 480,
    padding: theme.spacing(0, 1),
    '&:last-child': { paddingBottom: theme.spacing(1) },
  },
  row: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(0.6, 1),
    borderRadius: 6,
    '&:hover': {
      backgroundColor: theme.palette.action.hover,
    },
  },
  yearAvatar: {
    width: 28,
    height: 28,
    fontSize: '0.6rem',
    fontWeight: 700,
    backgroundColor: '#082D68',
    color: '#fff',
    flexShrink: 0,
  },
  playerName: {
    fontSize: '0.8rem',
    fontWeight: 500,
    flex: 1,
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
  },
  birthChip: {
    fontSize: '0.6rem',
    height: 18,
    fontWeight: 700,
    flexShrink: 0,
  },
}));

export default function HappenedPlayers({ players, title }) {
  const classes = useStyles();
  const today = new Date();
  const [playerReport, setPlayerReport] = useState(null);
  const [playerId, setPlayerId] = useState(0);

  const getCountry = (countryName) => allCountries.find(c => c.description === countryName);

  const openPlayer = (row) => {
    trackCardClick('nati_oggi');
    setPlayerId(row.ID);
    ARBApi.getAllByID('playerDetails', row.ID).then((report) => {
      const fallback = { data: { ...row, date: row.birth }, seasons: [] };
      setPlayerReport(report?.data ? report : fallback);
    });
  };

  return (
    <Card className={classes.root}>
      <CardHeader
        avatar={
          <Chip
            label={<Moment format="D MMM">{today}</Moment>}
            size="small"
            style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }}
          />
        }
        title={title}
        subheader="Cagliari Calcio"
      />
      <CardContent className={classes.content}>
        <SectionLabel>Giocatori</SectionLabel>
        {players.length === 0 && (
          <Typography style={{ fontSize: '0.8rem', color: 'rgba(0,0,0,0.4)', padding: '8px 8px' }}>
            Nessun giocatore nato oggi.
          </Typography>
        )}
        {players.map((row, i) => (
          <React.Fragment key={row.ID}>
            {i > 0 && <Divider style={{ margin: '2px 0' }} />}
            <div className={classes.row} style={{ cursor: 'pointer' }} onClick={() => openPlayer(row)}>
              <Avatar
                className={classes.yearAvatar}
                src={row.photo ? `https://www.archiviorossoblu.it/images/giocatori/${row.photo}` : undefined}
                alt={`${row.surname} ${row.name}`}
              >
                {!row.photo && <Moment locale='it' format="YY">{row.birth}</Moment>}
              </Avatar>
              {getCountry(row.country) && <Flag filename={getCountry(row.country).flag} country={row.country} />}
              <Typography className={classes.playerName}>
                {row.surname} {row.name}
              </Typography>
              <Chip
                label={<Moment locale='it' format="YYYY">{row.birth}</Moment>}
                size="small"
                color="primary"
                className={classes.birthChip}
              />
              <IconButton size="small" onClick={(e) => { e.stopPropagation(); openPlayer(row); }} style={{ padding: 2 }}>
                <MoreVertIcon style={{ fontSize: 14 }} />
              </IconButton>
            </div>
          </React.Fragment>
        ))}
      </CardContent>
      {playerId > 0 && playerReport && (
        <PlayerReport
          open={playerId > 0}
          handleClose={() => { setPlayerId(0); setPlayerReport(null); }}
          playerId={playerId}
          playerReport={playerReport}
        />
      )}
    </Card>
  );
}
