import React, { useState, useEffect, useRef, Fragment } from 'react';
import Waiting from './Waiting.js'
import { makeStyles } from '@mui/styles'
import * as ARBApi from '../../utils/ARBApi'
import Match from './Match'
import Players from './Players'
import HappenedMatches from './HappenedMatches'
import HappenedPlayers from './HappenedPlayers'
import RandomPlayer from './RandomPlayer'
import NewsCard from './NewsCard'
import RecentForm from './RecentForm'
import { Grid, Paper } from '@mui/material';

const useStyles = makeStyles((theme) => ({
  root: {
    flexGrow: 1,
  },
  paper: {
    height: '100%',
  },
}));

export default function GridCards() {
  const classes = useStyles();

  // Above-fold data — fetched immediately
  const [lastMatch, setLastMatch] = useState([]);
  const [nextMatch, setNextMatch] = useState([]);
  const [goals, setGoals] = useState([]);
  const [appareances, setAppareances] = useState([]);

  // Below-fold data — fetched on scroll
  const [happenedTodayMatch, setHappenedTodayMatch] = useState([]);
  const [happenedTodayBirth, setHappenedTodayBirth] = useState([]);
  const [randomPlayer, setRandomPlayer] = useState({});
  const [randomPlayerSeasons, setRandomPlayerSeasons] = useState([]);
  const [belowFoldLoaded, setBelowFoldLoaded] = useState(false);

  const sentinelRef = useRef(null);

  // Fetch above-fold immediately
  useEffect(() => {
    let isMounted = true;
    Promise.allSettled([
      ARBApi.getAll('lastMatch'),
      ARBApi.getAll('nextMatch'),
      ARBApi.getAll('goals'),
      ARBApi.getAll('appareances'),
    ]).then(([lastM, nextM, gol, app]) => {
      if (!isMounted) return;
      if (lastM.value) setLastMatch(lastM.value);
      if (nextM.value) setNextMatch(nextM.value);
      if (gol.value)   setGoals(gol.value);
      if (app.value)   setAppareances(app.value);
    });
    return () => { isMounted = false; };
  }, []);

  // Fetch below-fold when sentinel enters viewport
  useEffect(() => {
    if (belowFoldLoaded) return;
    const sentinel = sentinelRef.current;
    if (!sentinel) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return;
        observer.disconnect();
        setBelowFoldLoaded(true);
        let isMounted = true;
        Promise.allSettled([
          ARBApi.getAll('happeneds'),
          ARBApi.getAll('randomPlayer'),
        ]).then(([hap, rnd]) => {
          if (!isMounted) return;
          if (hap.value) {
            setHappenedTodayMatch(hap.value.matches?.league ?? []);
            setHappenedTodayBirth(hap.value.players ?? []);
          }
          if (rnd.value) {
            setRandomPlayer(rnd.value.player?.[0] ?? {});
            setRandomPlayerSeasons(rnd.value.seasons ?? []);
          }
        });
        return () => { isMounted = false; };
      },
      { rootMargin: '200px' }
    );
    observer.observe(sentinel);
    return () => observer.disconnect();
  }, [belowFoldLoaded]);

  return (
    <Fragment>
      {/* ── Riga 1: Forma, Ultima, Prossima, News ── */}
      <Grid item xs={12} sm={3}>
        <Paper className={classes.paper}>
          <RecentForm />
        </Paper>
      </Grid>
      {(lastMatch.length > 0) ? (
        <Grid item xs={12} sm={3}>
          <Paper className={classes.paper}>
            <Match match={lastMatch[0]} title='Ultima partita' />
          </Paper>
        </Grid>
      ) : (
        <Grid item xs={12} sm={3}>
          <Paper className={classes.paper}><Waiting variant="match" /></Paper>
        </Grid>
      )}
      {(nextMatch.length > 0) ? (
        <Grid item xs={12} sm={3}>
          <Paper className={classes.paper}>
            <Match match={nextMatch[0]} title='Prossima Partita' />
          </Paper>
        </Grid>
      ) : (
        <Grid item xs={12} sm={3}>
          <Paper className={classes.paper}><Waiting variant="match" /></Paper>
        </Grid>
      )}
      <Grid item xs={12} sm={3}>
        <Paper className={classes.paper}>
          <NewsCard compact />
        </Paper>
      </Grid>

      {/* ── Riga 2: Top Gol, Presenze, Accadde Oggi, Nati Oggi ── */}
      {(goals.length > 0) ? (
        <Grid item xs={12} sm={3}>
          <Paper className={classes.paper}>
            <Players players={goals} type='Gol' />
          </Paper>
        </Grid>
      ) : (
        <Grid item xs={12} sm={3}>
          <Paper className={classes.paper}><Waiting variant="player" /></Paper>
        </Grid>
      )}
      {(appareances.length > 0) ? (
        <Grid item xs={12} sm={3}>
          <Paper className={classes.paper}>
            <Players players={appareances} type='Presenze' />
          </Paper>
        </Grid>
      ) : (
        <Grid item xs={12} sm={3}>
          <Paper className={classes.paper}><Waiting variant="player" /></Paper>
        </Grid>
      )}
      {(happenedTodayMatch.length > 0) ? (
        <Grid item xs={12} sm={3}>
          <Paper className={classes.paper}>
            <HappenedMatches matches={happenedTodayMatch} title='Accadde Oggi - Partite' />
          </Paper>
        </Grid>
      ) : (
        <Grid item xs={12} sm={3}>
          <Paper className={classes.paper}><Waiting variant="list" /></Paper>
        </Grid>
      )}
      <Grid item xs={12} sm={3}>
        <Paper className={classes.paper}>
          <HappenedPlayers players={happenedTodayBirth} title='Nati Oggi' />
        </Paper>
      </Grid>

      {/* ── Sentinel: triggers below-fold fetch ── */}
      <Grid item xs={12}>
        <div ref={sentinelRef} style={{ height: 1 }} />
      </Grid>

      {/* ── Below fold ── */}
      {(randomPlayer.ID) ? (
        <Grid item xs={12} sm={3}>
          <Paper className={classes.paper}>
            <RandomPlayer player={randomPlayer} seasons={randomPlayerSeasons} type='Presenze' title='Uno a caso' />
          </Paper>
        </Grid>
      ) : (
        <Grid item xs={12} sm={3}>
          <Paper className={classes.paper}><Waiting variant="player" /></Paper>
        </Grid>
      )}
    </Fragment>
  );
}
