import React from 'react';
import { makeStyles } from '@mui/styles';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import Typography from '@mui/material/Typography';
import Avatar from '@mui/material/Avatar';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import IconButton from '@mui/material/IconButton';
import Skeleton from '@mui/material/Skeleton';
import EqualizerIcon from '@mui/icons-material/Equalizer';
import Tooltip from '@mui/material/Tooltip';
import { allCountries } from '../utils/generals';
import Flag from './Flag';

const useStyles = makeStyles((theme) => ({
  root: {
    borderTop: '4px solid #CA2331',
  },
  content: {
    padding: theme.spacing(0, 1),
    '&:last-child': { paddingBottom: theme.spacing(1) },
  },
  row: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(0.6, 1),
    borderRadius: 6,
    cursor: 'pointer',
    '&:hover': {
      backgroundColor: theme.palette.action.hover,
    },
  },
  rowNoClick: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(0.6, 1),
    borderRadius: 6,
  },
  rankAvatar: {
    width: 28,
    height: 28,
    fontSize: '0.6rem',
    fontWeight: 700,
    backgroundColor: '#CA2331',
    color: '#fff',
    flexShrink: 0,
  },
  playerName: {
    fontSize: '0.8rem',
    fontWeight: 500,
    flex: 1,
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
  },
  statChip: {
    fontSize: '0.6rem',
    height: 18,
    fontWeight: 700,
    flexShrink: 0,
  },
}));

export default function StatsSlider({ players, items, title, openDialog, type, openDialogAll, column }) {
  const classes = useStyles();

  return (
    <Card className={classes.root}>
      <CardHeader
        avatar={
          <Chip label={title} size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
        }
        action={
          <Tooltip title="Statistica completa" arrow>
            <IconButton onClick={() => openDialogAll(type, column)} color="primary" size="small">
              <EqualizerIcon />
            </IconButton>
          </Tooltip>
        }
      />
      <CardContent className={classes.content}>
        {players.length > 0 ? (
          players.slice(0, items).map((player, i) => {
            const countryData = allCountries.find(c => c.description === player.country);
            const isClickable = type !== 'coaches' && openDialog;
            return (
              <React.Fragment key={player.id}>
                {i > 0 && <Divider style={{ margin: '2px 0' }} />}
                <div
                  className={isClickable ? classes.row : classes.rowNoClick}
                  onClick={isClickable ? () => openDialog(player.id, type) : undefined}
                >
                  <Avatar
                    className={classes.rankAvatar}
                    src={player.image || undefined}
                    alt={`${player.surname} ${player.name}`}
                  >{!player.image && (i + 1)}</Avatar>
                  {countryData && <Flag filename={countryData.flag} country={player.country} />}
                  <Typography className={classes.playerName}>
                    {player.surname} {player.name}
                  </Typography>
                  <Chip
                    label={player.value}
                    size="small"
                    color="primary"
                    className={classes.statChip}
                  />
                </div>
              </React.Fragment>
            );
          })
        ) : (
          Array.from({ length: 6 }).map((_, i) => (
            <Skeleton key={i} animation="wave" height={32} style={{ margin: '4px 8px' }} />
          ))
        )}
      </CardContent>
    </Card>
  );
}
