import React, { useState } from 'react';
import PropTypes from 'prop-types';
import { makeStyles, withStyles, useTheme } from '@mui/styles';
import { alpha } from '@mui/material/styles';
import * as ARBApi from '../utils/ARBApi'
import { trackPlayerOpen } from '../utils/analytics'
import PlayerReport from '../components/dialogs/PlayerReport'
import Skeleton from '@mui/material/Skeleton';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import Table from '@mui/material/Table';
import TableHead from '@mui/material/TableHead';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableFooter from '@mui/material/TableFooter';
import TablePagination from '@mui/material/TablePagination';
import TableRow from '@mui/material/TableRow';
import Typography from '@mui/material/Typography';
import Avatar from '@mui/material/Avatar';
import Chip from '@mui/material/Chip';
import InputBase from '@mui/material/InputBase';
import Tooltip from '@mui/material/Tooltip';
import IconButton from '@mui/material/IconButton';
import FirstPageIcon from '@mui/icons-material/FirstPage';
import KeyboardArrowLeft from '@mui/icons-material/KeyboardArrowLeft';
import KeyboardArrowRight from '@mui/icons-material/KeyboardArrowRight';
import LastPageIcon from '@mui/icons-material/LastPage';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import SportsSoccerIcon from '@mui/icons-material/SportsSoccer';
import escareRegExp from 'escape-string-regexp'
import sortBy from 'sort-by'
import { allRoles, allCountries } from '../utils/generals'
import Flag from './Flag'
import Moment from 'react-moment';
import 'moment/locale/it';


const StyledTableRow = withStyles((theme) => ({
  root: {
    cursor: 'pointer',
    '&:nth-of-type(odd)': {
      backgroundColor: theme.palette.action.hover,
    },
    '&:hover': {
      backgroundColor: alpha(theme.palette.primary.main, 0.08),
    },
  }
}))(TableRow);

const useStyles1 = makeStyles((theme) => ({
  root: { flexShrink: 0, marginLeft: theme.spacing(2.5) },
}));

function TablePaginationActions(props) {
  const classes = useStyles1();
  const theme = useTheme();
  const { count, page, rowsPerPage, onPageChange } = props;

  return (
    <div className={classes.root}>
      <IconButton onClick={(e) => onPageChange(e, 0)} disabled={page === 0} aria-label="first page">
        {theme.direction === 'rtl' ? <LastPageIcon /> : <FirstPageIcon />}
      </IconButton>
      <IconButton onClick={(e) => onPageChange(e, page - 1)} disabled={page === 0} aria-label="previous page">
        {theme.direction === 'rtl' ? <KeyboardArrowRight /> : <KeyboardArrowLeft />}
      </IconButton>
      <IconButton onClick={(e) => onPageChange(e, page + 1)} disabled={page >= Math.ceil(count / rowsPerPage) - 1} aria-label="next page">
        {theme.direction === 'rtl' ? <KeyboardArrowLeft /> : <KeyboardArrowRight />}
      </IconButton>
      <IconButton onClick={(e) => onPageChange(e, Math.max(0, Math.ceil(count / rowsPerPage) - 1))} disabled={page >= Math.ceil(count / rowsPerPage) - 1} aria-label="last page">
        {theme.direction === 'rtl' ? <FirstPageIcon /> : <LastPageIcon />}
      </IconButton>
    </div>
  );
}

TablePaginationActions.propTypes = {
  count: PropTypes.number.isRequired,
  onPageChange: PropTypes.func.isRequired,
  page: PropTypes.number.isRequired,
  rowsPerPage: PropTypes.number.isRequired,
};

const useStyles = makeStyles((theme) => ({
  root: {
    borderTop: '4px solid #CA2331',
  },
  content: {
    padding: theme.spacing(0, 1),
    '&:last-child': { paddingBottom: theme.spacing(1) },
  },
  sectionLabel: {
    fontSize: '0.65rem',
    fontWeight: 800,
    letterSpacing: '0.08em',
    textTransform: 'uppercase',
    color: theme.palette.primary.main,
    padding: theme.spacing(1, 1, 0.25),
  },
  searchBar: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(0.5, 1),
    borderRadius: 6,
    backgroundColor: alpha(theme.palette.primary.main, 0.06),
    margin: theme.spacing(0.5, 1, 1),
  },
  header: {
    fontWeight: 700,
    fontSize: '0.75rem',
  },
  roleAvatar: {
    backgroundColor: '#CA2331',
    color: '#FFFFFF',
    width: 32,
    height: 32,
    fontSize: '0.65rem',
    fontWeight: 700,
  },
  nameText: {
    fontSize: '0.85rem',
    fontWeight: 500,
    color: '#082D68',
  },
  infoText: {
    fontSize: '0.8rem',
    color: theme.palette.text.secondary,
  },
}));

const ROLE_LABELS = { P: 'Portiere', D: 'Difensore', C: 'Centrocampista', A: 'Attaccante' };
const ROLE_COLORS = { P: '#6A0DAD', D: '#082D68', C: '#E87722', A: '#CA2331' };

export default function SearchPlayersDetails({ allPlayers = [], countryFilter, yearFilter, checkedPeriods }) {
  const classes = useStyles();

  const [openPlayer, setPlayerOpen] = useState(false);
  const [playerId, setPlayerId] = useState(0);
  const [playerReport, setPlayerReport] = useState([]);
  const [query, setQuery] = useState('');
  const [roleFilter, setRoleFilter] = useState(null);
  const [page, setPage] = useState(0);
  const rowsPerPage = 50;


  const handleChangePage = (event, newPage) => { setPage(newPage); };

  const handleQuery = (q) => { setQuery(q); setPage(0); };
  const handleRoleFilter = (r) => { setRoleFilter(prev => prev === r ? null : r); setPage(0); };

  const onSelectPlayer = (id) => {
    if (id > 0) {
      trackPlayerOpen('search_players', id);
      ARBApi.getAllByID(`playerDetails`, id).then((report) => {
        if (typeof report !== 'undefined') {
          setPlayerReport(report);
          setPlayerId(id);
          setPlayerOpen(true);
        }
      });
    }
  };

  const handleClickClosePlayer = () => { setPlayerOpen(false); setPlayerId(0); };

  const getFlag = (flag) => {
    const country = allCountries.filter(c => c.description === flag);
    return country[0].flag;
  };

  if (allPlayers.length > 0) {
    allPlayers.forEach(p => {
      p.roleabbrevation = allRoles.filter(r => r.description === p.role);
    });
  }

  let filteredPlayers = allPlayers;
  if (query) {
    const searchMatch = new RegExp(escareRegExp(query), 'i');
    filteredPlayers = allPlayers.filter(p => searchMatch.test(p.name) || searchMatch.test(p.surname));
  }
  if (roleFilter) {
    filteredPlayers = filteredPlayers.filter(p => p.roleabbrevation?.[0]?.role === roleFilter);
  }
  if (countryFilter) {
    filteredPlayers = filteredPlayers.filter(p => p.country === countryFilter);
  }
  if (yearFilter !== null && yearFilter !== undefined) {
    filteredPlayers = filteredPlayers.filter(p => {
      if (!p.date || p.date === '0000-00-00') return false;
      return parseInt(p.date.slice(0, 4)) === yearFilter;
    });
  } else if (checkedPeriods) {
    filteredPlayers = filteredPlayers.filter(p => {
      const isND = !p.date || p.date === '0000-00-00';
      if (isND) return !!checkedPeriods['ND'];
      const period = Math.floor(parseInt(p.date.slice(0, 4)) / 30) * 30;
      return checkedPeriods[period] !== false;
    });
  }
  filteredPlayers.sort(sortBy('surname'));

  return (
    <>
      {allPlayers.length === 0 ? (
        <Card className={classes.root}>
          <CardContent className={classes.content}>
            {Array.from({ length: 8 }).map((_, i) => (
              <Skeleton key={i} animation="wave" height={40} style={{ margin: '4px 8px' }} />
            ))}
          </CardContent>
        </Card>
      ) : (
        <Card className={classes.root}>
          <CardHeader
            avatar={
              <Chip
                label={`${filteredPlayers.length} giocatori`}
                size="small"
                style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }}
              />
            }
            title="Giocatori Cagliari Calcio"
            subheader="Archivio storico dalla stagione 1947/48"
          />
          <CardContent className={classes.content}>
            <Typography className={classes.sectionLabel}>Cerca</Typography>
            <div className={classes.searchBar}>
              <SportsSoccerIcon style={{ fontSize: '1rem', color: '#082D68', flexShrink: 0 }} />
              <InputBase
                placeholder="Nome o cognome…"
                style={{ width: 160, fontSize: '0.85rem' }}
                inputProps={{ 'aria-label': 'cerca giocatore' }}
                value={query}
                onChange={(e) => handleQuery(e.target.value)}
              />
            </div>

            <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center', padding: '0 8px 8px' }}>
              {/* Ruolo */}
              {Object.entries(ROLE_LABELS).map(([r, label]) => {
                const active = roleFilter === r;
                return (
                  <Tooltip key={r} title={label} arrow>
                    <Chip
                      label={r}
                      size="small"
                      onClick={() => handleRoleFilter(r)}
                      style={{
                        fontWeight: 700,
                        fontSize: '0.68rem',
                        backgroundColor: active ? ROLE_COLORS[r] : 'transparent',
                        color: active ? '#fff' : ROLE_COLORS[r],
                        border: `1.5px solid ${ROLE_COLORS[r]}`,
                        cursor: 'pointer',
                      }}
                    />
                  </Tooltip>
                );
              })}

              {(countryFilter || yearFilter) && (
                <span style={{ color: '#ccc', fontWeight: 300, fontSize: '1rem', margin: '0 2px' }}>|</span>
              )}
              {countryFilter && (
                <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                  <Flag filename={getFlag(countryFilter)} country={countryFilter} />
                  <Chip
                    label={countryFilter}
                    size="small"
                    style={{ fontWeight: 700, fontSize: '0.65rem', backgroundColor: '#082D68', color: '#fff', pointerEvents: 'none' }}
                  />
                </div>
              )}
              {countryFilter && (yearFilter || checkedPeriods) && (
                <span style={{ color: '#ccc', fontWeight: 300, fontSize: '1rem', margin: '0 2px' }}>|</span>
              )}
              {yearFilter ? (
                <Chip
                  label={`Nati nel ${yearFilter}`}
                  size="small"
                  style={{ fontWeight: 700, fontSize: '0.65rem', backgroundColor: '#F0C040', color: '#082D68', pointerEvents: 'none' }}
                />
              ) : checkedPeriods && Object.entries(checkedPeriods).map(([p, checked]) => checked ? (
                <Chip
                  key={p}
                  label={p === 'ND' ? 'N/D' : `${p}–${parseInt(p) + 29}`}
                  size="small"
                  style={{ fontWeight: 700, fontSize: '0.65rem', backgroundColor: p === 'ND' ? '#e0e0e0' : '#F0C040', color: p === 'ND' ? '#555' : '#082D68', pointerEvents: 'none' }}
                />
              ) : null)}
            </div>

            <Typography className={classes.sectionLabel}>Risultati</Typography>
            <TableContainer>
              <Table stickyHeader size="small">
                <TableHead>
                  <TableRow>
                    <TableCell className={classes.header}>Giocatore</TableCell>
                    <TableCell className={classes.header}>Ruolo</TableCell>
                    <TableCell className={classes.header}>Data Nascita</TableCell>
                    <TableCell className={classes.header}>Luogo Nascita</TableCell>
                    <TableCell className={classes.header} align="center"></TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {filteredPlayers
                    .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                    .map((row) => (
                      <StyledTableRow key={row.id} onClick={() => onSelectPlayer(row.id)}>
                        <TableCell>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                            <Avatar
                              src={row.photo ? `https://www.archiviorossoblu.it/images/giocatori/${row.photo}` : undefined}
                              alt={row.name}
                              style={{ width: 28, height: 28, flexShrink: 0 }}
                            />
                            <Flag filename={getFlag(row.country)} country={row.country} />
                            <Typography className={classes.nameText}>
                              {row.surname} {row.name}
                            </Typography>
                          </div>
                        </TableCell>
                        <TableCell>
                          <Avatar
                            className={classes.roleAvatar}
                            style={{ backgroundColor: ROLE_COLORS[row.roleabbrevation?.[0]?.role] ?? '#CA2331' }}
                          >
                            {row.roleabbrevation?.[0]?.role ?? '?'}
                          </Avatar>
                        </TableCell>
                        <TableCell>
                          <Typography className={classes.infoText}>
                            {row.date !== '0000-00-00'
                              ? <Moment locale='it' format="LL">{row.date}</Moment>
                              : 'ND'}
                          </Typography>
                        </TableCell>
                        <TableCell>
                          <Typography className={classes.infoText}>{row.birthplace}</Typography>
                        </TableCell>
                        <TableCell align="center">
                          <IconButton size="small" onClick={(e) => { e.stopPropagation(); onSelectPlayer(row.id); }}>
                            <MoreVertIcon fontSize="small" />
                          </IconButton>
                        </TableCell>
                      </StyledTableRow>
                    ))}
                </TableBody>
                <TableFooter>
                  <TableRow>
                    <TablePagination
                      rowsPerPageOptions={[50]}
                      colSpan={5}
                      count={filteredPlayers.length}
                      rowsPerPage={rowsPerPage}
                      page={page}
                      slotProps={{ select: { inputProps: { 'aria-label': 'rows per page' }, native: true } }}
                      onPageChange={handleChangePage}
                      ActionsComponent={TablePaginationActions}
                    />
                  </TableRow>
                </TableFooter>
              </Table>
            </TableContainer>
          </CardContent>
        </Card>
      )}
      {openPlayer && (
        <PlayerReport
          open={openPlayer}
          handleClose={handleClickClosePlayer}
          playerReport={playerReport}
          playerId={playerId}
        />
      )}
    </>
  );
}
