import React, { useState, useEffect } from 'react';
import PropTypes from 'prop-types';
import { Tabs, Tab, Box, useMediaQuery } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import { useLocation } from 'react-router-dom';
import SportsSoccerIcon from '@mui/icons-material/SportsSoccer';
import PeopleIcon from '@mui/icons-material/People';
import EventIcon from '@mui/icons-material/Event';
import SportsIcon from '@mui/icons-material/Sports';
import Card from '@mui/material/Card';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import SeasonList from './SeasonList.js'
import Players from './Players.js'
import MatchesPanel from './MatchesPanel.js'
import Referees from './Referees.js'
import Sidebar from './Sidebar.js'
import Typography from '@mui/material/Typography';
import ShareButtons from './ShareButtons';
import YouTubeLink from './YouTubeLink';
import { makeStyles } from '@mui/styles';
import Collapse from '@mui/material/Collapse';

const useStyles = makeStyles((theme) => ({
  navCard: {
    borderTop: '4px solid #CA2331',
    marginBottom: theme.spacing(1),
  },
  navHeader: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1.5),
    padding: theme.spacing(1, 2),
    backgroundImage: 'url(https://www.archiviorossoblu.it/images/header-gradient-bg.jpg)',
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    position: 'relative',
    '&::before': {
      content: '""',
      position: 'absolute',
      inset: 0,
      background: 'rgba(8,45,104,0.60)',
    },
    '& > *': {
      position: 'relative',
      zIndex: 1,
    },
  },
  brand: {
    fontWeight: 800,
    fontSize: '1.6rem',
    color: '#F0C040',
    textDecoration: 'none',
    flex: 1,
  },
  hint: {
    fontSize: '0.72rem',
    color: '#CA2331',
    fontWeight: 600,
    textAlign: 'left',
    padding: '4px 16px',
    backgroundColor: 'rgba(202,35,49,0.06)',
    borderTop: '1px solid rgba(202,35,49,0.12)',
  },
}));

function TabPanel(props) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`nav-tabpanel-${index}`}
      aria-labelledby={`nav-tab-${index}`}
      style={{ height: '100%' }}
      {...other}
    >
      {value === index && (
        <Box style={{ height: '100%', boxSizing: 'border-box' }}>
          <div style={{ height: '100%' }}>{children}</div>
        </Box>
      )}
    </div>
  );
}

TabPanel.propTypes = {
  children: PropTypes.node,
  index: PropTypes.any.isRequired,
  value: PropTypes.any.isRequired,
};

function a11yProps(index) {
  return {
    id: `nav-tab-${index}`,
    'aria-controls': `nav-tabpanel-${index}`,
  };
}

function LinkTab(props) {
  return (
    <Tab
      component="a"
      onClick={(event) => {
        event.preventDefault();
      }}
      {...props}
    />
  );
}

export default function SeasonDetails({
  players,
  matches,
  cupMatches,
  seasonID,
  seasons,
  countries,
  coaches,
  referees,
  onSeasonSelect,
  onMatchSelect,
  onPlayerSelect,
  seasonLabel,
  roles,
  rightPanel }) {
  const classes = useStyles();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const { pathname } = useLocation();
  const isHome = pathname === '/' || pathname === '/stagioni';
  const [valueTab, setValueTab] = useState(0);

  useEffect(() => {
    if (seasonID > 0) {
      setValueTab(1);
    }
  }, [seasonID]);

  const handleChange = (event, newValue) => {
    setValueTab(newValue);
  };
  let tabEnabled = true;

  if (seasonID > 0) {
    tabEnabled = false;
  }

  return (
    <div>
      <Card className={classes.navCard}>
        <div className={classes.navHeader}>
          <Sidebar iconColor="#F0C040" />
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, flex: 1 }}>
            <img src="https://www.archiviorossoblu.it/images/sun-gold-sella-bg.png" alt="logo" title="ArchivioRossoBlu" style={{ width: 80, height: 80, flexShrink: 0 }} />
            <Typography component="a" href="/cagliari-calcio" className={classes.brand} style={{ flex: 'none' }}>
              <span className="brand-short" title="ArchivioRossoBlu">ARB</span>
              <span className="brand-full">ArchivioRossoBlu</span>
            </Typography>
          </div>
          <YouTubeLink />
          <ShareButtons />
          <Chip label={isHome ? 'Home' : 'Cagliari Calcio'} size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
        </div>
        <Divider />
        <Tabs
          variant="scrollable"
          value={valueTab}
          onChange={handleChange}
          aria-label="navigazione stagioni"
          textColor="primary"
          indicatorColor="primary"
        >
          <LinkTab label="Stagioni" icon={<SportsSoccerIcon />} href="/home" {...a11yProps(0)} />
          <LinkTab label="Rosa" icon={<PeopleIcon />} href="/players" {...a11yProps(1)} disabled={tabEnabled} />
          <LinkTab label="Partite" icon={<EventIcon />} href="/matches" {...a11yProps(2)} disabled={tabEnabled} />
          <LinkTab label="Arbitri" icon={<SportsIcon />} href="/referees" {...a11yProps(3)} disabled={tabEnabled} />
        </Tabs>
        <Collapse in={tabEnabled}>
          <div className={classes.hint}>
            ← seleziona una stagione per sbloccare le sezioni
          </div>
        </Collapse>
      </Card>
      <div style={isMobile
        ? { display: 'flex', flexDirection: 'column', gap: 8 }
        : { display: 'flex', alignItems: 'stretch', gap: 8, height: 480 }
      }>
        <div style={isMobile ? {} : { flex: 1, minWidth: 0, height: '100%' }}>
          <TabPanel value={valueTab} index={0}>
            <SeasonList
              seasons={seasons}
              onSeasonSelect={onSeasonSelect}
            />
          </TabPanel>
          <TabPanel value={valueTab} index={1} selected>
            <Players
              players={players}
              coaches={coaches}
              seasonID={seasonID}
              seasonLabel={seasonLabel}
              countries={countries}
              roles={roles}
              onPlayerSelect={onPlayerSelect}
            />
          </TabPanel>
          <TabPanel value={valueTab} index={2}>
            <MatchesPanel
              matches={matches}
              cupMatches={cupMatches}
              seasonID={seasonID}
              seasonLabel={seasonLabel}
              onMatchSelect={onMatchSelect}
            />
          </TabPanel>
          <TabPanel value={valueTab} index={3}>
            <Referees referees={referees} seasonID={seasonID} seasonLabel={seasonLabel} />
          </TabPanel>
        </div>
        {rightPanel && (
          <div style={isMobile
            ? { padding: 8 }
            : { width: 460, flexShrink: 0, height: '100%' }
          }>
            {rightPanel}
          </div>
        )}
      </div>
    </div>
  );
}