import React, { useState, useEffect } from 'react';
import HomeIcon from '@mui/icons-material/Home';
import FlightTakeoffIcon from '@mui/icons-material/FlightTakeoff';
import SentimentVeryDissatisfiedIcon from '@mui/icons-material/SentimentVeryDissatisfied';
import SentimentNeutralIcon from '@mui/icons-material/SentimentNeutral';
import SentimentSatisfiedAltIcon from '@mui/icons-material/SentimentSatisfiedAlt';
import SentimentVerySatisfiedIcon from '@mui/icons-material/SentimentVerySatisfied';
import { makeStyles } from '@mui/styles';
import SectionLabel from '../SectionLabel';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import Typography from '@mui/material/Typography';
import Chip from '@mui/material/Chip';
import Tooltip from '@mui/material/Tooltip';
import Box from '@mui/material/Box';
import Divider from '@mui/material/Divider';
import Moment from 'react-moment';
import * as ARBApi from '../../utils/ARBApi';
import { allSeasons, allTeams } from '../../utils/generals';

const RESULT_CONFIG = {
  V: { label: 'V', color: '#4caf50', tooltip: 'Vittoria', tooltipPlural: 'Vittorie' },
  P: { label: 'P', color: '#9e9e9e', tooltip: 'Pareggio', tooltipPlural: 'Pareggi' },
  S: { label: 'S', color: '#CA2331', tooltip: 'Sconfitta', tooltipPlural: 'Sconfitte' },
};

const useStyles = makeStyles((theme) => ({
  root: {
    borderTop: '4px solid #CA2331',
    height: '100%',
    display: 'flex',
    flexDirection: 'column',
  },
  content: {
    flex: 1,
    padding: theme.spacing(0, 1, 1),
    '&:last-child': { paddingBottom: theme.spacing(1) },
  },
  formRow: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(1.5, 0, 1),
  },
  resultChip: {
    width: 36,
    height: 36,
    borderRadius: '50%',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontWeight: 800,
    fontSize: '0.85rem',
    color: '#fff',
    cursor: 'default',
    flexShrink: 0,
  },
  matchRow: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(0.5, 1),
  },
  matchText: {
    fontSize: '0.75rem',
    flex: 1,
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    color: theme.palette.text.secondary,
  },
  score: {
    fontSize: '0.78rem',
    fontWeight: 700,
    color: '#082D68',
    flexShrink: 0,
    width: 36,
    textAlign: 'right',
    fontVariantNumeric: 'tabular-nums',
  },
}));

function getResult(match) {
  // lastMatch uses goalshome/goalsaway, season matches use gh/ga
  const gh = match.goalshome ?? match.gh;
  const ga = match.goalsaway ?? match.ga;
  if (match.played !== 'Y' || gh === null || gh === undefined || gh === '') return null;
  const isCagliariHome = match.home === 'Cagliari';
  const cag = isCagliariHome ? parseInt(gh) : parseInt(ga);
  const opp = isCagliariHome ? parseInt(ga) : parseInt(gh);
  const key = cag > opp ? 'V' : cag === opp ? 'P' : 'S';
  return { ...RESULT_CONFIG[key], gh, ga };
}

export default function RecentForm() {
  const classes = useStyles();
  const [matches, setMatches] = useState([]);

  useEffect(() => {
    // Find the current season (last in allSeasons)
    const currentSeason = allSeasons[0];
    if (!currentSeason) return;

    ARBApi.getAllByID('matches', currentSeason.id).then((data) => {
      if (!Array.isArray(data)) return;
      const played = data
        .filter(m => m.played === 'Y')
        .slice(-5);
      setMatches(played);
    });
  }, []);

  const results = matches.map(m => ({ ...m, result: getResult(m) })).filter(m => m.result);

  const summary = { V: 0, P: 0, S: 0 };
  results.forEach(m => { if (m.result) summary[m.result.label]++; });

  // Score: V=3, P=1, S=0 — max 15
  const score = results.length > 0 ? (summary.V * 3 + summary.P * 1) / (results.length * 3) : null;
  const mood = score === null ? null
    : score >= 0.7 ? { Icon: SentimentVerySatisfiedIcon,  color: '#4caf50', label: 'In forma!' }
    : score >= 0.45 ? { Icon: SentimentSatisfiedAltIcon,  color: '#8bc34a', label: 'Discreta forma' }
    : score >= 0.25 ? { Icon: SentimentNeutralIcon,        color: '#ff9800', label: 'Forma altalenante' }
    :                 { Icon: SentimentVeryDissatisfiedIcon, color: '#CA2331', label: 'Momento difficile' };

  return (
    <Card className={classes.root}>
      <CardHeader
        avatar={
          <Chip label="Forma" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
        }
        title="Forma recente"
        subheader="Ultime 5 partite"
      />
      <CardContent className={classes.content}>
        {/* Pallini V/P/S */}
        <div className={classes.formRow}>
          {/* Slot vuoti a sinistra per mantenere sempre 5 posizioni */}
          {Array.from({ length: Math.max(0, 5 - results.length) }).map((_, i) => (
            <div key={`empty-${i}`} className={classes.resultChip} style={{ backgroundColor: 'rgba(0,0,0,0.1)' }} />
          ))}
          {results.map((m, i) => (
            <Tooltip key={i} title={`${m.result.tooltip} · ${m.home} ${m.result.gh}–${m.result.ga} ${m.away}`} arrow>
              <div className={classes.resultChip} style={{ backgroundColor: m.result.color }}>
                {m.result.label}
              </div>
            </Tooltip>
          ))}
        </div>

        {/* Riepilogo V/P/S */}
        {results.length > 0 && (
          <Box display="flex" justifyContent="center" gap={2} pb={1}>
            {['V', 'P', 'S'].map(k => (
              <Box key={k} textAlign="center">
                <Typography style={{ fontSize: '1rem', fontWeight: 800, color: RESULT_CONFIG[k].color }}>{summary[k]}</Typography>
                <Typography style={{ fontSize: '0.6rem', color: 'rgba(0,0,0,0.45)', textTransform: 'uppercase' }}>{summary[k] === 1 ? RESULT_CONFIG[k].tooltip : RESULT_CONFIG[k].tooltipPlural}</Typography>
              </Box>
            ))}
          </Box>
        )}

        <Divider style={{ margin: '2px 0 4px' }} />
        <SectionLabel>Dettaglio</SectionLabel>

        {/* Lista partite — dalla più recente */}
        {[...results].reverse().map((m, i) => {
          const isHome = m.home === 'Cagliari';
          const opponent = isHome ? m.away : m.home;
          const homeTeam = allTeams.find(t => t.name === m.home);
          const stadium = homeTeam?.stadium || null;
          return (
            <div key={i} className={classes.matchRow}>
              <div className={classes.resultChip} style={{ backgroundColor: m.result.color, width: 22, height: 22, fontSize: '0.6rem' }}>
                {m.result.label}
              </div>
              <Tooltip title={isHome ? 'Casa' : 'Trasferta'} arrow>
                {isHome
                  ? <HomeIcon style={{ fontSize: 14, color: '#082D68', flexShrink: 0 }} />
                  : <FlightTakeoffIcon style={{ fontSize: 14, color: '#9e9e9e', flexShrink: 0 }} />
                }
              </Tooltip>
              <Typography className={classes.matchText}>
                {opponent}
                <span style={{ color: 'rgba(0,0,0,0.38)', fontSize: '0.65rem', marginLeft: 4 }}>
                  <Moment locale='it' format="DD/MM/YY">{m.date}</Moment>
                  {stadium && ` · ${stadium}`}
                </span>
              </Typography>
              <Typography className={classes.score}>
                {m.result.gh}–{m.result.ga}
              </Typography>
            </div>
          );
        })}
        {/* Mood icon */}
        {mood && (
          <Tooltip title={mood.label} arrow>
            <Box display="flex" justifyContent="center" pt={1}>
              <mood.Icon style={{ fontSize: 36, color: mood.color }} />
            </Box>
          </Tooltip>
        )}
      </CardContent>
    </Card>
  );
}
