import React, { useState, useEffect, useMemo } from 'react';
import SectionLabel from '../SectionLabel';
import { trackPlayerOpen } from '../../utils/analytics';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import Chip from '@mui/material/Chip';
import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import Avatar from '@mui/material/Avatar';
import Checkbox from '@mui/material/Checkbox';
import Skeleton from '@mui/material/Skeleton';
import Divider from '@mui/material/Divider';
import { makeStyles } from '@mui/styles';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { allCountries } from '../../utils/generals';
import Flag from '../Flag';
import * as ARBApi from '../../utils/ARBApi';
import PlayerReport from '../dialogs/PlayerReport';

const useStyles = makeStyles((theme) => ({
  root: { borderTop: '4px solid #CA2331' },
  content: {
    padding: '0 8px 8px',
    '&:last-child': { paddingBottom: 8 },
  },
  playerRow: {
    display: 'flex',
    alignItems: 'center',
    gap: 8,
    padding: '5px 8px',
    borderRadius: 6,
    cursor: 'pointer',
    '&:hover': { backgroundColor: theme.palette.action.hover },
  },
  playerName: {
    fontSize: '0.8rem',
    fontWeight: 500,
    color: '#082D68',
    flex: 1,
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
  },
  roleAvatar: {
    width: 24,
    height: 24,
    fontSize: '0.6rem',
    fontWeight: 700,
    color: '#fff',
    flexShrink: 0,
  },
}));

const ROLE_COLORS = { P: '#6A0DAD', D: '#082D68', C: '#E87722', A: '#CA2331' };
const ROLE_MAP = { Portiere: 'P', Difensore: 'D', 'Difensore-Terzino': 'D', 'Difensore-Centrale': 'D', Centrocampista: 'C', 'Centrocampista-Centrale': 'C', 'Centrocampista-Laterale': 'C', Fantasista: 'C', Attaccante: 'A', 'Attaccante-Prima Punta': 'A', 'Attaccante-Seconda Punta': 'A' };

const getFlag = (countryName) => {
  const c = allCountries.find(c => c.description === countryName);
  return c?.flag ?? null;
};

const CustomYearTick = ({ x, y, payload, index }) => {
  if (index % 10 !== 0) return null;
  return <text x={x} y={y + 12} textAnchor="middle" fontSize={9} fill="#666">{payload.value}</text>;
};

function PlayerRow({ p, onSelect }) {
  const classes = useStyles();
  const abbr = ROLE_MAP[p.role] ?? '?';
  return (
    <div className={classes.playerRow} onClick={() => onSelect(p.id)}>
      <Avatar className={classes.roleAvatar} style={{ backgroundColor: ROLE_COLORS[abbr] ?? '#888' }}>{abbr}</Avatar>
      <Typography className={classes.playerName}>{p.name}</Typography>
    </div>
  );
}

function PlayerList({ players, onSelect }) {
  if (!players.length) return null;
  return (
    <Box style={{ maxHeight: 260, overflowY: 'auto', marginTop: 8, borderTop: '1px solid #f0f0f0' }}>
      {players.map(p => <PlayerRow key={p.id} p={p} onSelect={onSelect} />)}
    </Box>
  );
}

// ─── Nazionalità ──────────────────────────────────────────────────────────────

function NationalityTab({ players, selectedCountry, onSelectCountry }) {
  const countryMap = useMemo(() => {
    const map = {};
    players.forEach(p => {
      if (!map[p.country]) map[p.country] = [];
      map[p.country].push(p);
    });
    return map;
  }, [players]);

  const sorted = Object.entries(countryMap).sort((a, b) => b[1].length - a[1].length || a[0].localeCompare(b[0]));
  const maxCount = sorted[0]?.[1].length ?? 1;

  return (
    <Box style={{ maxHeight: 300, overflowY: 'auto' }}>
      {sorted.map(([country, plist]) => {
        const flag = getFlag(country);
        const pct = (plist.length / maxCount) * 100;
        const isSelected = selectedCountry === country;
        return (
          <Box
            key={country}
            onClick={() => onSelectCountry(prev => prev === country ? null : country)}
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              padding: '5px 8px',
              borderRadius: 6,
              cursor: 'pointer',
              backgroundColor: isSelected ? 'rgba(8,45,104,0.07)' : 'transparent',
            }}
            sx={{ '&:hover': { backgroundColor: 'action.hover' } }}
          >
            {flag ? <Flag filename={flag} country={country} /> : <Box style={{ width: 20, height: 14 }} />}
            <Typography style={{ fontSize: '0.78rem', fontWeight: isSelected ? 700 : 500, color: '#222', width: 120, flexShrink: 0 }}>
              {country}
            </Typography>
            <Box style={{ flex: 1, height: 8, borderRadius: 4, backgroundColor: '#f0f0f0', overflow: 'hidden' }}>
              <Box style={{ width: `${pct}%`, height: '100%', backgroundColor: isSelected ? '#F0C040' : '#082D68', borderRadius: 4, transition: 'width 0.3s' }} />
            </Box>
            <Typography style={{ fontSize: '0.72rem', fontWeight: 700, color: '#082D68', width: 28, textAlign: 'right', flexShrink: 0 }}>
              {plist.length}
            </Typography>
          </Box>
        );
      })}
    </Box>
  );
}

// ─── Dettaglio paese ──────────────────────────────────────────────────────────

function CountryDetail({ players, country }) {
  const flag = getFlag(country);

  const byCity = useMemo(() => {
    const normalize = (raw) => {
      if (!raw) return 'N/D';
      const cleaned = raw.replace(/\s*\(.*?\)/g, '').trim();
      if (!cleaned) return 'N/D';
      return cleaned.toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
    };
    const map = {};
    players.forEach(p => {
      const city = normalize(p.birthplace);
      if (!map[city]) map[city] = 0;
      map[city]++;
    });
    const entries = Object.entries(map).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
    const nd = entries.filter(([c]) => c === 'N/D');
    const rest = entries.filter(([c]) => c !== 'N/D');
    return [...rest, ...nd];
  }, [players]);

  return (
    <>
      <Box display="flex" alignItems="center" gap={1} style={{ padding: '4px 8px 4px' }}>
        {flag && <Flag filename={flag} country={country} />}
        <SectionLabel style={{ padding: 0 }}>
          {country} · {players.length} giocatori
        </SectionLabel>
      </Box>
      <Box style={{ maxHeight: 260, overflowY: 'auto', padding: '0 0 4px' }}>
        {byCity.map(([city, count], i) => (
          <Box key={city}>
            {i > 0 && <Divider style={{ margin: '2px 0' }} />}
            <Box display="flex" alignItems="center" justifyContent="space-between" style={{ padding: '5px 8px' }}>
              <Typography style={{ fontSize: '0.78rem', fontWeight: 500, color: city === 'N/D' ? '#aaa' : '#222' }}>
                {city}
              </Typography>
              <Chip label={count} size="small" style={{ height: 18, fontSize: '0.65rem', fontWeight: 700, backgroundColor: '#f0f0f0', color: '#555' }} />
            </Box>
          </Box>
        ))}
      </Box>
    </>
  );
}

// ─── Anno di nascita ──────────────────────────────────────────────────────────

function BirthYearTab({ players, onSelect, selectedYear: selectedYearProp, onSelectYear, onPeriodsChange }) {
  const [selectedYearLocal, setSelectedYearLocal] = useState(null);
  const selectedYear = selectedYearProp !== undefined ? selectedYearProp : selectedYearLocal;
  const setSelectedYear = onSelectYear ?? setSelectedYearLocal;

  const yearMap = useMemo(() => {
    const map = {};
    players.forEach(p => {
      if (!p.date || p.date === '0000-00-00') return;
      const y = parseInt(p.date.slice(0, 4));
      if (!map[y]) map[y] = [];
      map[y].push(p);
    });
    return map;
  }, [players]);

  const allYears = Object.keys(yearMap).map(Number);
  const minYear = Math.min(...allYears);
  const maxYear = Math.max(...allYears);

  const periods = useMemo(() => {
    const minP = Math.floor(minYear / 30) * 30;
    const maxP = Math.floor(maxYear / 30) * 30;
    const result = {};
    for (let p = minP; p <= maxP; p += 30) result[p] = true;
    return result;
  }, [minYear, maxYear]);

  const [checkedPeriods, setCheckedPeriods] = useState(() => {
    const minP = Math.floor(1960 / 30) * 30;
    const maxP = Math.floor(2006 / 30) * 30;
    const allP = Object.keys(periods || {}).map(Number);
    const result = {};
    allP.forEach(p => { result[p] = p >= minP && p <= maxP; });
    result['ND'] = false;
    return result;
  });

  useEffect(() => {
    setCheckedPeriods(prev => {
      const result = {};
      Object.keys(periods).forEach(p => {
        result[p] = prev[p] !== undefined ? prev[p] : true;
      });
      result['ND'] = prev['ND'] !== undefined ? prev['ND'] : false;
      return result;
    });
  }, [periods]);

  useEffect(() => {
    if (onPeriodsChange) onPeriodsChange(checkedPeriods);
  }, [checkedPeriods, onPeriodsChange]);

  const togglePeriod = (p) => {
    setCheckedPeriods(prev => ({ ...prev, [p]: !prev[p] }));
    setSelectedYear(null);
  };

  const ndCount = players.filter(p => !p.date || p.date === '0000-00-00').length;

  const chartData = useMemo(() => {
    const data = [];
    for (let y = minYear; y <= maxYear; y++) {
      const period = Math.floor(y / 30) * 30;
      if (!checkedPeriods[period]) continue;
      data.push({ year: y, count: yearMap[y]?.length ?? 0 });
    }
    return data;
  }, [minYear, maxYear, yearMap, checkedPeriods]);

  const selectedPlayers = selectedYear ? (yearMap[selectedYear] ?? []) : [];

  return (
    <>
      <Box display="flex" flexWrap="wrap" gap={0} style={{ padding: '0 4px 4px' }}>
        {Object.keys(periods).map(p => {
          const period = parseInt(p);
          const checked = !!checkedPeriods[period];
          return (
            <Box key={period} display="flex" alignItems="center" onClick={() => togglePeriod(period)} style={{ cursor: 'pointer', userSelect: 'none' }}>
              <Checkbox checked={checked} size="small" style={{ color: '#082D68', padding: 2 }} />
              <Typography style={{ fontSize: '0.65rem', color: checked ? '#082D68' : '#aaa', fontWeight: checked ? 700 : 400 }}>
                {period}–{period + 29}
              </Typography>
            </Box>
          );
        })}
        {ndCount > 0 && (
          <Box display="flex" alignItems="center" onClick={() => togglePeriod('ND')} style={{ cursor: 'pointer', userSelect: 'none' }}>
            <Checkbox checked={!!checkedPeriods['ND']} size="small" style={{ color: '#aaa', padding: 2 }} />
            <Typography style={{ fontSize: '0.65rem', color: checkedPeriods['ND'] ? '#555' : '#aaa', fontWeight: checkedPeriods['ND'] ? 700 : 400 }}>
              N/D ({ndCount})
            </Typography>
          </Box>
        )}
      </Box>
      <ResponsiveContainer width="100%" height={260}>
        <BarChart data={chartData} margin={{ top: 8, right: 8, left: -28, bottom: 0 }}
          onClick={(e) => {
            if (e?.activePayload?.[0]) {
              const y = e.activePayload[0].payload.year;
              setSelectedYear(prev => prev === y ? null : y);
            }
          }}
        >
          <XAxis dataKey="year" tick={<CustomYearTick />} interval={0} />
          <YAxis tick={{ fontSize: 9, fill: '#666' }} />
          <Tooltip
            formatter={(v, _, props) => [`${v} giocatori`, props.payload.year]}
            labelFormatter={() => ''}
            contentStyle={{ fontSize: '0.72rem' }}
          />
          <Bar dataKey="count" radius={[2, 2, 0, 0]}>
            {chartData.map((entry) => (
              <Cell key={entry.year} fill={entry.year === selectedYear ? '#F0C040' : '#082D68'} cursor="pointer" />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
      {selectedYear && (
        <Box style={{ padding: '4px 8px 0' }}>
          <Typography style={{ fontSize: '0.72rem', fontWeight: 700, color: '#082D68' }}>
            Nati nel {selectedYear} — {selectedPlayers.length} giocatori
          </Typography>
          <PlayerList players={selectedPlayers} onSelect={onSelect} />
        </Box>
      )}
    </>
  );
}

// ─── Main ─────────────────────────────────────────────────────────────────────

export default function ExploraPlayers({ onlyNationality, onlyBirthYear, onlyCountryDetail, allPlayers = [], selectedCountry: selectedCountryProp, onSelectCountry: onSelectCountryProp, selectedYear, onSelectYear, onPeriodsChange }) {
  const classes = useStyles();
  const [selectedCountryLocal, setSelectedCountryLocal] = useState('Italia');
  const [playerReport, setPlayerReport] = useState(null);
  const [playerId, setPlayerId] = useState(null);

  const selectedCountry = selectedCountryProp !== undefined ? selectedCountryProp : selectedCountryLocal;
  const setSelectedCountry = onSelectCountryProp ?? setSelectedCountryLocal;

  const onSelect = (id) => {
    trackPlayerOpen('explora_players', id);
    ARBApi.getAllByID('playerDetails', id).then(report => {
      if (report) { setPlayerReport(report); setPlayerId(id); }
    });
  };

  const countryPlayers = useMemo(() =>
    selectedCountry ? allPlayers.filter(p => p.country === selectedCountry) : [],
    [allPlayers, selectedCountry]
  );

  const skeletonCard = (height) => (
    <Card className={classes.root}>
      <CardHeader avatar={<Skeleton variant="rounded" width={72} height={24} />} subheader={<Skeleton width="50%" height={14} />} />
      <CardContent className={classes.content}>
        <Skeleton animation="wave" height={height} variant="rectangular" style={{ borderRadius: 4 }} />
      </CardContent>
    </Card>
  );

  const showNationality = !onlyBirthYear && !onlyCountryDetail;
  const showBirthYear = !onlyNationality && !onlyCountryDetail;
  const showCountryDetail = onlyCountryDetail;

  return (
    <>
      <Box display="flex" flexDirection="column" gap={2} width="100%">
        {/* Nazionalità + Città di nascita */}
        {showNationality && (allPlayers.length === 0 ? skeletonCard(260) : (
          <Card className={classes.root} style={{ height: '100%' }}>
            <CardHeader
              avatar={<Chip label="Nazionalità" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />}
              subheader="Giocatori per paese di origine"
            />
            <CardContent className={classes.content}>
              <NationalityTab players={allPlayers} selectedCountry={selectedCountry} onSelectCountry={setSelectedCountry} />
            </CardContent>
          </Card>
        ))}

        {/* Città di nascita */}
        {showCountryDetail && selectedCountry && allPlayers.length > 0 && (
          <Card className={classes.root} style={{ height: '100%' }}>
            <CardHeader
              avatar={<Chip label="Città di nascita" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />}
              subheader={
                <Box display="flex" alignItems="center" gap={0.5}>
                  {getFlag(selectedCountry) && <Flag filename={getFlag(selectedCountry)} country={selectedCountry} />}
                  <span>{`${selectedCountry} · ${countryPlayers.length} giocatori`}</span>
                </Box>
              }
            />
            <CardContent className={classes.content}>
              <CountryDetail players={countryPlayers} country={selectedCountry} />
            </CardContent>
          </Card>
        )}
        {showCountryDetail && !selectedCountry && allPlayers.length > 0 && (
          <Card className={classes.root} style={{ height: '100%' }}>
            <CardHeader
              avatar={<Chip label="Città di nascita" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />}
              subheader="Seleziona una nazione"
            />
          </Card>
        )}
        {showCountryDetail && allPlayers.length === 0 && skeletonCard(200)}

        {/* Anno di nascita */}
        {showBirthYear && (allPlayers.length === 0 ? skeletonCard(280) : (
          <Card className={classes.root} style={{ height: '100%' }}>
            <CardHeader
              avatar={<Chip label="Anno di nascita" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />}
              subheader={
                <Box display="flex" alignItems="center" gap={0.5}>
                  {selectedCountry && getFlag(selectedCountry) && <Flag filename={getFlag(selectedCountry)} country={selectedCountry} />}
                  <span>{selectedCountry ? `${selectedCountry} · ${countryPlayers.length} giocatori` : `Tutti · ${allPlayers.length} giocatori`}</span>
                </Box>
              }
            />
            <CardContent className={classes.content}>
              <BirthYearTab players={selectedCountry ? countryPlayers : allPlayers} onSelect={onSelect} selectedYear={selectedYear} onSelectYear={onSelectYear} onPeriodsChange={onPeriodsChange} />
            </CardContent>
          </Card>
        ))}
      </Box>
      {playerReport && (
        <PlayerReport
          open={!!playerReport}
          handleClose={() => { setPlayerReport(null); setPlayerId(null); }}
          playerReport={playerReport}
          playerId={playerId}
        />
      )}
    </>
  );
}
