/**
 * GA4 event tracking helper.
 * Only fires if gtag is available (i.e. consent granted via CookieYes).
 */
function gtag(...args) {
  if (typeof window.gtag !== 'function') return;
  window.gtag(...args);
}

export function trackCardClick(cardType) {
  gtag('event', 'card_click', { card_type: cardType });
}

export function trackPageView(pageName) {
  gtag('event', 'page_view_section', { page_name: pageName });
}

export function trackPlayerOpen(source, playerId) {
  gtag('event', 'player_open', { source, player_id: playerId });
}

export function trackSeasonSelect(seasonId, seasonYear) {
  gtag('event', 'season_select', { season_id: seasonId, season_year: seasonYear });
}

export function trackNextPlayer() {
  gtag('event', 'random_player_next');
}
