import React, { useEffect, useRef, useState } from 'react';
import { makeStyles } from '@mui/styles';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import Typography from '@mui/material/Typography';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import parse from 'html-react-parser';
import Moment from 'react-moment';
import 'moment/locale/it';
import * as ARBApi from '../../utils/ARBApi';
import { parseMatchReport, splitList } from '../../utils/matchReport';

const useStyles = makeStyles((theme) => ({
  title: {
    background: 'linear-gradient(135deg, #082D68 0%, #0d3d8f 100%)',
    padding: theme.spacing(1.5, 2, 1),
  },
  sectionLabel: {
    fontSize: '0.65rem',
    fontWeight: 800,
    letterSpacing: '0.08em',
    textTransform: 'uppercase',
    color: theme.palette.primary.main,
    padding: theme.spacing(1, 0, 0.5),
  },
  statRow: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: theme.spacing(1),
    padding: theme.spacing(0.6, 0),
    borderRadius: 6,
    '&:hover': { backgroundColor: theme.palette.action.hover },
  },
  infoRow: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(0.5, 0),
  },
  chipRow: {
    display: 'flex',
    flexWrap: 'wrap',
    gap: theme.spacing(0.5),
    padding: theme.spacing(0.5, 0, 1),
  },
  playerChip: {
    fontSize: '0.68rem',
    height: 22,
    backgroundColor: 'rgba(8,45,104,0.08)',
    color: '#082D68',
    fontWeight: 500,
  },
  bookingChip: {
    fontSize: '0.68rem',
    height: 22,
    backgroundColor: 'rgba(255,193,7,0.15)',
    color: '#7a5000',
    fontWeight: 500,
  },
  lineupBlock: {
    marginBottom: theme.spacing(1),
  },
  lineupTeam: {
    fontSize: '0.72rem',
    fontWeight: 800,
    color: '#082D68',
    textTransform: 'uppercase',
    letterSpacing: '0.05em',
    marginBottom: theme.spacing(0.5),
  },
  refereeRow: {
    display: 'flex',
    alignItems: 'center',
    gap: theme.spacing(1),
    padding: theme.spacing(0.5, 0),
    marginBottom: theme.spacing(0.5),
  },
}));

export default function MatchReport({ open, handleClose, title, report, played, opponentTeamId, match }) {
  const classes = useStyles();
  const descriptionElementRef = useRef(null);
  const [matchesWithTeam, setMatcheWithTeam] = useState([]);

  useEffect(() => {
    let isMounted = true;
    if (open) {
      const { current: descriptionElement } = descriptionElementRef;
      if (descriptionElement !== null) descriptionElement.focus();
    }
    if (opponentTeamId > 0 && played === 'N') {
      ARBApi.getAllByID(`teams`, opponentTeamId).then((data) => {
        if (isMounted && data) setMatcheWithTeam(data);
      });
    }
    return () => { isMounted = false; };
  }, [open, played, opponentTeamId]);

  let stats = null;
  let displayTitle = title;

  if (opponentTeamId > 0 && matchesWithTeam && matchesWithTeam.length > 0 && played === 'N') {
    stats = { v: 0, p: 0, s: 0 };
    matchesWithTeam.forEach((match) => {
      if (match.gf === match.gc) stats.p += 1;
      else if (match.home === 'Cagliari' && match.gc > match.gf) stats.v += 1;
      else if (match.away === 'Cagliari' && match.gf > match.gc) stats.v += 1;
      else stats.s += 1;
    });
    displayTitle = `Precedenti ${title}`;
    report = null;
  }

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      scroll="paper"
      aria-labelledby="match-dialog-title"
    >
      <DialogTitle id="match-dialog-title" className={classes.title}>
        <Typography style={{ fontWeight: 700, fontSize: '1rem', color: '#F0C040' }}>
          {displayTitle}
        </Typography>
      </DialogTitle>
      <DialogContent>
        {stats ? (
          <>
            <Typography className={classes.sectionLabel}>Precedenti</Typography>
            <Divider style={{ marginBottom: 8 }} />
            {[
              { label: 'Incontri disputati', value: matchesWithTeam.length, color: '#082D68' },
              { label: 'Vittorie', value: stats.v, color: '#4caf50' },
              { label: 'Pareggi', value: stats.p, color: '#082D68' },
              { label: 'Sconfitte', value: stats.s, color: '#CA2331' },
            ].map((item) => (
              <div key={item.label} className={classes.statRow}>
                <Typography style={{ fontSize: '0.82rem', fontWeight: 500 }}>{item.label}</Typography>
                <Chip
                  label={item.value}
                  size="small"
                  style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, backgroundColor: item.color, color: '#fff' }}
                />
              </div>
            ))}
          </>
        ) : (
          <>
            {match && (
              <>
                <Typography className={classes.sectionLabel}>Info</Typography>
                <Divider style={{ marginBottom: 8 }} />
                {[
                  { label: 'Data', value: (() => { const t = match.date?.split(' ')?.[1]; const hasTime = t && t !== '00:00:00'; return <span><Moment locale='it' format="LL">{match.date}</Moment>{hasTime && ` ⏰ ${t.slice(0,5)}`}</span>; })() },
                  { label: 'Giornata', value: `Giornata ${match.day}` },
                  ...(match.played === 'Y' ? [{
                    label: 'Esito', value: (() => {
                      const isCagliariHome = match.home === 'Cagliari';
                      const cag = isCagliariHome ? parseInt(match.gh) : parseInt(match.ga);
                      const opp = isCagliariHome ? parseInt(match.ga) : parseInt(match.gh);
                      const { label: l, color } = cag > opp
                        ? { label: 'Vittoria', color: '#4caf50' }
                        : cag === opp
                        ? { label: 'Pareggio', color: '#9e9e9e' }
                        : { label: 'Sconfitta', color: '#CA2331' };
                      return <Chip label={l} size="small" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, backgroundColor: color, color: '#fff' }} />;
                    })()
                  }] : []),
                ].map((item) => (
                  <div key={item.label} className={classes.statRow}>
                    <Typography style={{ fontSize: '0.82rem', fontWeight: 500 }}>{item.label}</Typography>
                    <Typography style={{ fontSize: '0.82rem', color: 'rgba(0,0,0,0.6)' }}>{item.value}</Typography>
                  </div>
                ))}
                <Divider style={{ margin: '8px 0' }} />
              </>
            )}
            {report ? (() => {
              const p = parseMatchReport(report, match?.home, match?.away);
              const hasParsed = p.referee || p.scorers || p.bookings || p.homeLineup?.length || p.awayLineup?.length;
              if (!hasParsed) {
                return (
                  <>
                    <Typography className={classes.sectionLabel}>Resoconto</Typography>
                    <Divider style={{ marginBottom: 8 }} />
                    <Typography style={{ fontSize: '0.85rem', lineHeight: 1.6 }}>{parse(report)}</Typography>
                  </>
                );
              }
              return (
                <div style={{ width: '100%' }}>
                  {p.referee && (
                    <div style={{ marginBottom: 8 }}>
                      <Typography className={classes.sectionLabel}>Arbitro</Typography>
                      <Divider style={{ marginBottom: 6 }} />
                      <div className={classes.refereeRow}>
                        <span>👔</span>
                        <Typography style={{ fontSize: '0.82rem', fontWeight: 500 }}>{p.referee}</Typography>
                      </div>
                    </div>
                  )}
                  {p.scorers && (
                    <div style={{ marginBottom: 8 }}>
                      <Typography className={classes.sectionLabel}>⚽ Marcatori</Typography>
                      <Divider style={{ marginBottom: 6 }} />
                      {splitList(p.scorers).map((s, i) => (
                        <div key={i} style={{ display: 'block', padding: '3px 0' }}>
                          <Typography style={{ fontSize: '0.82rem', fontWeight: 500 }}>{s}</Typography>
                        </div>
                      ))}
                    </div>
                  )}
                  {p.bookings && (
                    <div style={{ marginBottom: 8 }}>
                      <Typography className={classes.sectionLabel}>🟨 Ammoniti</Typography>
                      <Divider style={{ marginBottom: 6 }} />
                      <div className={classes.chipRow}>
                        {splitList(p.bookings).map((s, i) => (
                          <Chip key={i} label={s} size="small" className={classes.bookingChip} />
                        ))}
                      </div>
                    </div>
                  )}
                  {p.expulsions && (
                    <div style={{ marginBottom: 8 }}>
                      <Typography className={classes.sectionLabel}>🟥 Espulsi</Typography>
                      <Divider style={{ marginBottom: 6 }} />
                      <div className={classes.chipRow}>
                        {splitList(p.expulsions).map((s, i) => (
                          <Chip key={i} label={s} size="small" style={{ fontSize: '0.68rem', height: 22, backgroundColor: 'rgba(202,35,49,0.12)', color: '#CA2331', fontWeight: 500 }} />
                        ))}
                      </div>
                    </div>
                  )}
                  {(p.homeLineup || p.awayLineup) && (
                    <div style={{ marginBottom: 8 }}>
                      <Typography className={classes.sectionLabel}>Formazioni</Typography>
                      <Divider style={{ marginBottom: 8 }} />
                      {p.homeLineup && (
                        <div className={classes.lineupBlock}>
                          <Typography className={classes.lineupTeam}>
                            {match?.home}{p.homeCoach ? ` – All. ${p.homeCoach}` : ''}
                          </Typography>
                          <div className={classes.chipRow}>
                            {p.homeLineup.map((s, i) => (
                              <Chip key={i} label={s} size="small" className={classes.playerChip} />
                            ))}
                          </div>
                        </div>
                      )}
                      {p.awayLineup && (
                        <div className={classes.lineupBlock}>
                          <Typography className={classes.lineupTeam}>
                            {match?.away}{p.awayCoach ? ` – All. ${p.awayCoach}` : ''}
                          </Typography>
                          <div className={classes.chipRow}>
                            {p.awayLineup.map((s, i) => (
                              <Chip key={i} label={s} size="small" className={classes.playerChip} />
                            ))}
                          </div>
                        </div>
                      )}
                    </div>
                  )}
                  {p.notes && (
                    <div style={{ marginBottom: 8 }}>
                      <Typography className={classes.sectionLabel}>Note</Typography>
                      <Divider style={{ marginBottom: 6 }} />
                      <Typography style={{ fontSize: '0.8rem', lineHeight: 1.6, color: 'rgba(0,0,0,0.7)' }}>{p.notes}</Typography>
                    </div>
                  )}
                </div>
              );
            })() : null}
          </>
        )}
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClose} color="primary" size="small">Chiudi</Button>
      </DialogActions>
    </Dialog>
  );
}
