import React, { useState } from 'react';
import { allSeasons, thisSeason } from '../../utils/generals';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import Chip from '@mui/material/Chip';
import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import Tabs from '@mui/material/Tabs';
import Tab from '@mui/material/Tab';
import { makeStyles } from '@mui/styles';

const useStyles = makeStyles(() => ({
  root: {
    borderTop: '4px solid #CA2331',
  },
  content: {
    padding: '0 8px 8px',
    '&:last-child': { paddingBottom: 8 },
  },
}));

const LEAGUE_COLOR = {
  'Tutti': '#555',
  'A':     '#082D68',
  'B':     '#CA2331',
  'C1':    '#E87722',
  '1RS':   '#6A0DAD',
};

const LEAGUES = Object.keys(LEAGUE_COLOR);

function computeRecords(seasons) {
  if (!seasons.length) return [];

  const maxBy = (field, label, icon, color, format) => {
    const s = seasons.reduce((best, cur) =>
      parseInt(cur[field]) > parseInt(best[field]) ? cur : best
    );
    return { label, icon, color, year: s.year, value: format(s[field]) };
  };

  const minBy = (field, label, icon, color, format) => {
    const s = seasons.reduce((best, cur) =>
      parseInt(cur[field]) < parseInt(best[field]) ? cur : best
    );
    return { label, icon, color, year: s.year, value: format(s[field]) };
  };

  return [
    maxBy('points', 'Più punti',          '🏅', '#082D68', v => `${v} pt`),
    maxBy('v',      'Più vittorie',        '✅', '#4caf50', v => `${v} V`),
    minBy('l',      'Meno sconfitte',      '🛡️', '#6A0DAD', v => `${v} S`),
    maxBy('gf',     'Più gol fatti',       '⚽', '#E87722', v => `${v} gol`),
    minBy('gs',     'Meno gol subiti',     '🧤', '#082D68', v => `${v} gol`),
    maxBy('dr',     'Miglior diff. reti',  '📈', '#4caf50', v => `+${v}`),
  ];
}

const validSeasons = allSeasons.filter(s => parseInt(s.position) > 0 && parseInt(s.id) !== thisSeason);

const recordsByLeague = {
  'Tutti': computeRecords(validSeasons),
  ...Object.fromEntries(
    ['A', 'B', 'C1', '1RS'].map(l => [
      l,
      computeRecords(validSeasons.filter(s => s.league === l)),
    ])
  ),
};

export default function SeasonRecords() {
  const classes = useStyles();
  const [tab, setTab] = useState(0);

  const league = LEAGUES[tab];
  const records = recordsByLeague[league];
  const color = LEAGUE_COLOR[league];

  return (
    <Card className={classes.root}>
      <CardHeader
        avatar={<Chip label="Record" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />}
        subheader="Primati per stagione (campionato)"
      />
      <Tabs
        value={tab}
        onChange={(_, v) => setTab(v)}
        variant="fullWidth"
        textColor="primary"
        indicatorColor="primary"
        style={{ borderBottom: `2px solid ${color}`, minHeight: 32 }}
      >
        {LEAGUES.map(l => (
          <Tab
            key={l}
            label={l === 'Tutti' ? 'Tutti' : `Serie ${l}`}
            style={{ minHeight: 32, fontSize: '0.65rem', fontWeight: 700, color: tab === LEAGUES.indexOf(l) ? color : '#aaa' }}
          />
        ))}
      </Tabs>
      <CardContent className={classes.content}>
        {records.length === 0 ? (
          <Typography style={{ fontSize: '0.75rem', color: '#aaa', padding: '12px 8px' }}>
            Nessuna stagione disponibile.
          </Typography>
        ) : (
          records.map((r) => (
            <Box
              key={r.label}
              display="flex"
              alignItems="center"
              justifyContent="space-between"
              style={{ padding: '6px 8px', borderBottom: '1px solid #f0f0f0' }}
            >
              <Box display="flex" alignItems="center" gap={1}>
                <Typography style={{ fontSize: '1rem', lineHeight: 1 }}>{r.icon}</Typography>
                <Typography style={{ fontSize: '0.75rem', color: '#444', fontWeight: 500 }}>{r.label}</Typography>
              </Box>
              <Box display="flex" alignItems="center" gap={1}>
                <Typography style={{ fontSize: '0.7rem', color: '#999' }}>{r.year}</Typography>
                <Chip
                  label={r.value}
                  size="small"
                  style={{ fontWeight: 700, fontSize: '0.7rem', backgroundColor: r.color, color: '#fff', height: 20 }}
                />
              </Box>
            </Box>
          ))
        )}
      </CardContent>
    </Card>
  );
}
