import axios from 'axios';

const api = process.env.REACT_APP_ATTR_API_URL || 'https://www.archiviorossoblu.it/api'

let token = localStorage.token

if (!token)
  token = localStorage.token = Math.random().toString(36).substr(-8)

const instance = axios.create({
  baseURL: api,
  timeout: 10000,
  headers: {
    'Accept': 'application/json',
    'Authorization': token,
  }
});

const TTL       = 5 * 60 * 1000; // 5 minuti (fresh)
const STALE_TTL = 30 * 60 * 1000; // 30 minuti (stale ma usabile come fallback)

function getCached(key, allowStale = false) {
  try {
    const raw = sessionStorage.getItem(`arb_cache_${key}`);
    if (!raw) return null;
    const entry = JSON.parse(raw);
    const age = Date.now() - entry.ts;
    if (age > STALE_TTL) { sessionStorage.removeItem(`arb_cache_${key}`); return null; }
    if (age > TTL && !allowStale) return null;
    return entry.data;
  } catch { return null; }
}

function setCached(key, data) {
  try {
    sessionStorage.setItem(`arb_cache_${key}`, JSON.stringify({ data, ts: Date.now() }));
  } catch {}
}

async function fetchWithRetry(url, key, retries = 2, delay = 1500) {
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const res = await instance.get(url);
      setCached(key, res.data);
      return res.data;
    } catch (error) {
      if (attempt < retries) {
        await new Promise(r => setTimeout(r, delay));
      } else {
        console.warn(`[ARBApi] Failed after ${retries + 1} attempts: ${url}`, error?.response?.status);
        // Fallback: restituisce dati stale se disponibili
        return getCached(key, true) ?? null;
      }
    }
  }
}

export const getAll = async (controller) => {
  const key = controller;
  const cached = getCached(key);
  if (cached) return cached;
  return fetchWithRetry(`${controller}.php`, key);
};

export const getFresh = async (controller) => {
  try {
    const res = await instance.get(`${controller}.php`);
    return res.data;
  } catch { return null; }
};

export const getAllByID = async (controller, id) => {
  const key = `${controller}:${id}`;
  const cached = getCached(key);
  if (cached) return cached;
  return fetchWithRetry(`${controller}.php?id=${id}`, key);
};
