import React, { useEffect, useState } from 'react';
import { useParams, useNavigate, useLocation } from 'react-router-dom';
import SEO from '../components/SEO';
import IconButton from '@mui/material/IconButton';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import Breadcrumbs from '@mui/material/Breadcrumbs';
import Link from '@mui/material/Link';
import NavigateNextIcon from '@mui/icons-material/NavigateNext';
import { makeStyles } from '@mui/styles';
import Card from '@mui/material/Card';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import Typography from '@mui/material/Typography';
import Avatar from '@mui/material/Avatar';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Paper from '@mui/material/Paper';
import Box from '@mui/material/Box';
import Grid from '@mui/material/Grid';
import Skeleton from '@mui/material/Skeleton';
import CircularProgress from '@mui/material/CircularProgress';
import EventIcon from '@mui/icons-material/Event';
import SportsSoccerIcon from '@mui/icons-material/SportsSoccer';
import CakeIcon from '@mui/icons-material/Cake';
import StyleIcon from '@mui/icons-material/Style';
import HeightIcon from '@mui/icons-material/Height';
import FitnessCenterIcon from '@mui/icons-material/FitnessCenter';
import StarIcon from '@mui/icons-material/Star';
import Moment from 'react-moment';
import { BarChart, Bar, XAxis, YAxis, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import MuiTooltip from '@mui/material/Tooltip';
import 'moment/locale/it';
import Sidebar from '../components/Sidebar';
import Flag from '../components/Flag';
import ShareButtons from '../components/ShareButtons';
import YouTubeLink from '../components/YouTubeLink';
import PlayerShareCard from '../components/PlayerShareCard';
import Footer from '../components/Footer';
import { allCountries } from '../utils/generals';
import * as ARBApi from '../utils/ARBApi';

const stripHtml = (str) => str ? str.replace(/<[^>]*>/g, '').trim() : '';

const parseFirstMatch = (str) => {
  if (!str) return null;
  const m = str.match(/^(\d{2})\/(\d{2})\/(\d{2,4})/);
  if (!m) return null;
  const year = m[3].length === 2 ? `20${m[3]}` : m[3];
  return new Date(`${year}-${m[2]}-${m[1]}`);
};

const getFirstMatchGame = (str) => {
  if (!str) return null;
  const m = str.match(/^\d{2}\/\d{2}\/\d{2,4}\s*(.*)/);
  return m?.[1]?.trim() || null;
};

const useStyles = makeStyles((theme) => ({
    navCard: {
        borderTop: '4px solid #CA2331',
        marginBottom: theme.spacing(1),
    },
    navHeader: {
        display: 'flex',
        alignItems: 'center',
        gap: theme.spacing(1.5),
        padding: theme.spacing(1, 2),
        backgroundImage: 'url(https://www.archiviorossoblu.it/images/header-gradient-bg.jpg)',
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        position: 'relative',
        '&::before': {
            content: '""',
            position: 'absolute',
            inset: 0,
            background: 'rgba(8,45,104,0.60)',
        },
        '& > *': {
            position: 'relative',
            zIndex: 1,
        },
    },
    brand: {
        fontWeight: 800,
        fontSize: '1.6rem',
        color: '#F0C040',
        textDecoration: 'none',
        flex: 1,
    },
    content: {
        maxWidth: 1200,
        margin: '0 auto',
        padding: theme.spacing(2),
    },
    sectionLabel: {
        fontSize: '0.65rem !important',
        fontWeight: '800 !important',
        letterSpacing: '0.08em !important',
        textTransform: 'uppercase',
        color: `${theme.palette.primary.main} !important`,
        padding: theme.spacing(1.5, 0, 0.5),
    },
    infoRow: {
        display: 'flex',
        alignItems: 'center',
        flexWrap: 'wrap',
        gap: theme.spacing(1),
        padding: theme.spacing(0.5, 0),
    },
    header: {
        fontSize: '0.72rem !important',
        fontWeight: '700 !important',
        color: '#082D68 !important',
        padding: '4px 8px !important',
    },
    cell: {
        padding: '4px 8px !important',
        fontSize: '0.78rem !important',
    },
    tableRow: {
        '&:hover': { backgroundColor: theme.palette.action.hover },
    },
    avatarBlue: {
        width: '22px !important',
        height: '22px !important',
        fontSize: '0.6rem !important',
        fontWeight: '700 !important',
        backgroundColor: '#082D68 !important',
        color: '#fff !important',
    },
    panelCard: {
        padding: theme.spacing(2),
        height: '100%',
        boxSizing: 'border-box',
    },
    statRow: {
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        padding: theme.spacing(0.75, 0),
        borderBottom: '1px solid rgba(0,0,0,0.06)',
        '&:last-child': { borderBottom: 'none' },
    },
    statLabel: {
        display: 'flex',
        alignItems: 'center',
        gap: theme.spacing(0.75),
        fontSize: '0.8rem',
        color: 'rgba(0,0,0,0.6)',
    },
    statValue: {
        fontWeight: '700 !important',
        fontSize: '1.1rem !important',
        color: '#082D68 !important',
    },
}));

export default function PlayerPage() {
    const { id, slug } = useParams(); // slug is cosmetic, id is used for API
    const navigate = useNavigate();
    const location = useLocation();
    const canGoBack = location.key !== 'default';
    const classes = useStyles();
    const [playerReport, setPlayerReport] = useState(null);
    const [loading, setLoading] = useState(true);
    const [coords, setCoords] = useState(null);
    const [mapLoading, setMapLoading] = useState(false);
    const [shareText, setShareText] = useState('ArchivioRossoBlu - Statistiche Cagliari Calcio');

    useEffect(() => {
        setCoords(null);
        setMapLoading(false);
        ARBApi.getAllByID('playerDetails', id).then((report) => {
            setPlayerReport(report?.data ? report : null);
            if (report?.data?.data) {
                const { name, surname } = report.data.data;
                setShareText(`${name} ${surname} - ArchivioRossoBlu`);
            }
            setLoading(false);
        });
    }, [id]);

    useEffect(() => {
        if (!playerReport?.data) return;
        const { birthplace, country } = playerReport.data;
        const query = [birthplace, country].filter(Boolean).join(', ');
        if (!birthplace) return;
        setMapLoading(true);
        fetch(`https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(query)}&format=json&limit=1`, {
            headers: { 'Accept-Language': 'it' }
        })
            .then(r => r.json())
            .then(results => {
                if (results?.[0]) {
                    setCoords({ lat: parseFloat(results[0].lat), lon: parseFloat(results[0].lon) });
                }
                setMapLoading(false);
            })
            .catch(() => { setMapLoading(false); });
    }, [playerReport]);

    const getFlag = (countryName) => allCountries.find(c => c.description === countryName)?.flag;

    const playerName = playerReport?.data
      ? `${playerReport.data.name} ${playerReport.data.surname}`
      : slug?.replace(/-/g, ' ');

    return (
        <Box>
            <SEO
              title={playerName}
              description={playerReport?.data
                ? `Scheda di ${playerName}: presenze, gol, stagioni e statistiche con il Cagliari Calcio.`
                : 'Scheda giocatore – ArchivioRossoBlu'
              }
              path={`/cagliari-calcio/giocatore/${slug}/${id}`}
            />
            {/* Header */}
            <Card className={classes.navCard}>
                <div className={classes.navHeader}>
                    <Sidebar iconColor="#F0C040" />
                    <div style={{ display: 'flex', alignItems: 'center', gap: 6, flex: 1 }}>
                        <img src="https://www.archiviorossoblu.it/images/sun-gold-sella-bg.png" alt="logo" title="ArchivioRossoBlu" style={{ width: 80, height: 80, flexShrink: 0 }} />
            <Typography component="a" href="/cagliari-calcio" className={classes.brand} style={{ flex: 'none' }}>
                            <span className="brand-short" title="ArchivioRossoBlu">ARB</span>
                            <span className="brand-full">ArchivioRossoBlu</span>
                        </Typography>
                    </div>
                    <YouTubeLink />
                    <ShareButtons url={window.location.href} text={shareText} />
                    <Chip label="Giocatore" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
                </div>
            </Card>

            {loading && (
                <Box className={classes.content}>
                    <Grid container spacing={2} style={{ marginBottom: 16 }}>
                        {[0, 1, 2].map(i => (
                            <Grid item xs={12} sm={4} key={i}>
                                <Skeleton variant="rectangular" height={200} style={{ borderRadius: 8 }} />
                            </Grid>
                        ))}
                    </Grid>
                    {Array.from({ length: 6 }).map((_, i) => (
                        <Skeleton key={i} animation="wave" height={40} style={{ marginBottom: 6 }} />
                    ))}
                </Box>
            )}

            {!loading && !playerReport && (
                <Box display="flex" justifyContent="center" mt={6}>
                    <Typography color="textSecondary">Giocatore non trovato.</Typography>
                </Box>
            )}

            {!loading && playerReport && (() => {
                const { data, seasons } = playerReport;
                const flagFile = getFlag(data.country);

                const totals = (seasons || []).reduce((acc, s) => ({
                    appareances: acc.appareances + (parseInt(s.appareances) !== -1 ? (parseInt(s.appareances) || 0) : 0),
                    goal: acc.goal + (parseInt(s.goal) !== -1 ? (parseInt(s.goal) || 0) : 0),
                    yellowcard: acc.yellowcard + (parseInt(s.yellowcard) !== -1 ? (parseInt(s.yellowcard) || 0) : 0),
                    redcard: acc.redcard + (parseInt(s.redcard) !== -1 ? (parseInt(s.redcard) || 0) : 0),
                }), { appareances: 0, goal: 0, yellowcard: 0, redcard: 0 });

                return (
                    <>
                        <Box className={classes.content}>
                            <Box display="flex" alignItems="center" gap={1} mb={1.5}>
                                {canGoBack && (
                                    <IconButton size="small" onClick={() => navigate(-1)} style={{ color: '#082D68', padding: 4 }}>
                                        <ArrowBackIcon fontSize="small" />
                                    </IconButton>
                                )}
                                <Breadcrumbs separator={<NavigateNextIcon fontSize="small" />} aria-label="breadcrumb" style={{ flex: 1 }}>
                                    <Link href="/cagliari-calcio" underline="hover" style={{ fontSize: '0.78rem', color: '#082D68', fontWeight: 600 }}>Home</Link>
                                    <Link href="/cagliari-calcio/giocatori" underline="hover" style={{ fontSize: '0.78rem', color: '#082D68', fontWeight: 600 }}>Giocatori</Link>
                                    <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.5)', fontWeight: 500 }}>
                                        {data.name} {data.surname}
                                    </Typography>
                                </Breadcrumbs>
                                <PlayerShareCard data={data} seasons={seasons} />
                            </Box>
                            {/* Three-column panel */}
                            <Grid container spacing={2} style={{ marginBottom: 16 }} alignItems="stretch">
                                {/* Info */}

                                <Grid item xs={12} sm={4}>
                                    <Card className={classes.panelCard} elevation={1}>
                                        <Box display="flex" alignItems="center" gap={2} mb={1.5}>
                                            <Avatar
                                                src={data.photo ? `https://www.archiviorossoblu.it/images/giocatori/${data.photo}` : undefined}
                                                alt={`${data.name} ${data.surname}`}
                                                style={{ width: 72, height: 72, border: '3px solid #082D68', flexShrink: 0 }}
                                            />
                                            <Box>
                                                <Box display="flex" alignItems="center" gap={1} mb={0.5}>
                                                    {flagFile && <Flag filename={flagFile} country={data.country} size="md" />}
                                                    <Typography style={{ fontWeight: 700, fontSize: '1.15rem', color: '#082D68' }}>
                                                        {data.name} {data.surname}
                                                    </Typography>
                                                </Box>
                                                {data.role && (
                                                    <Chip
                                                        label={data.role}
                                                        size="small"
                                                        style={{ backgroundColor: '#F0C040', color: '#082D68', fontWeight: 700, fontSize: '0.65rem', height: 20 }}
                                                    />
                                                )}
                                            </Box>
                                        </Box>
                                        <Divider style={{ marginBottom: 8 }} />
                                        <div className={classes.infoRow}>
                                            <Avatar style={{ width: 22, height: 22, fontSize: '0.6rem', backgroundColor: '#CA2331', color: '#fff' }}>
                                                <CakeIcon style={{ fontSize: 13 }} />
                                            </Avatar>
                                            <Box>
                                                <Typography style={{ fontSize: '0.82rem', color: 'rgba(0,0,0,0.6)' }}>
                                                    {data.date && data.date !== '0000-00-00'
                                                        ? <Moment locale='it' format="LL">{data.date}</Moment>
                                                        : '—'
                                                    }
                                                </Typography>
                                                {data.birthplace && (
                                                    <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.45)' }}>
                                                        {[data.birthplace, data.country].filter(Boolean).join(', ')}
                                                    </Typography>
                                                )}
                                            </Box>
                                        </div>
                                        {(parseInt(data.height) > 0 || parseInt(data.weight) > 0) && (
                                            <div className={classes.infoRow} style={{ marginTop: 2 }}>
                                                {parseInt(data.height) > 0 && (
                                                    <>
                                                        <HeightIcon style={{ fontSize: 16, color: '#082D68' }} />
                                                        <Typography style={{ fontSize: '0.82rem', color: 'rgba(0,0,0,0.6)' }}>{data.height} cm</Typography>
                                                    </>
                                                )}
                                                {parseInt(data.weight) > 0 && (
                                                    <>
                                                        <FitnessCenterIcon style={{ fontSize: 14, color: '#082D68', marginLeft: parseInt(data.height) > 0 ? 8 : 0 }} />
                                                        <Typography style={{ fontSize: '0.82rem', color: 'rgba(0,0,0,0.6)' }}>{data.weight} kg</Typography>
                                                    </>
                                                )}
                                            </div>
                                        )}
                                        {data.nickname && (
                                            <Typography style={{ fontSize: '0.82rem', fontStyle: 'italic', color: 'rgba(0,0,0,0.55)', marginTop: 6 }}>
                                                "{data.nickname}"
                                            </Typography>
                                        )}
                                        {data.note && (
                                            <Typography style={{ fontSize: '0.8rem', lineHeight: 1.6, color: 'rgba(0,0,0,0.65)', marginTop: 6 }}>
                                                {stripHtml(data.note)}
                                            </Typography>
                                        )}
                                    </Card>
                                </Grid>

                                {/* Riepilogo */}
                                <Grid item xs={12} sm={4}>
                                    <Card className={classes.panelCard} elevation={1}>
                                        <Typography className={classes.sectionLabel} style={{ paddingTop: 0 }}>Riepilogo carriera</Typography>
                                        <Box mt={1}>
                                            <div className={classes.statRow}>
                                                <span className={classes.statLabel}>
                                                    <EventIcon style={{ fontSize: 16, color: '#082D68' }} /> Presenze
                                                </span>
                                                <Typography className={classes.statValue}>{totals.appareances}</Typography>
                                            </div>
                                            <div className={classes.statRow}>
                                                <span className={classes.statLabel}>
                                                    <SportsSoccerIcon style={{ fontSize: 16, color: '#CA2331' }} /> Gol
                                                </span>
                                                <Typography className={classes.statValue} style={{ color: '#CA2331' }}>{totals.goal}</Typography>
                                            </div>
                                            <div className={classes.statRow}>
                                                <span className={classes.statLabel}>
                                                    <span style={{ display: 'inline-block', width: 12, height: 16, backgroundColor: '#FDDB3A', borderRadius: 2, flexShrink: 0 }} />
                                                    Ammonizioni
                                                </span>
                                                <Typography className={classes.statValue} style={{ color: '#b8860b' }}>{totals.yellowcard}</Typography>
                                            </div>
                                            <div className={classes.statRow}>
                                                <span className={classes.statLabel}>
                                                    <StyleIcon style={{ fontSize: 16, color: '#CA2331' }} /> Espulsioni
                                                </span>
                                                <Typography className={classes.statValue} style={{ color: '#CA2331' }}>{totals.redcard}</Typography>
                                            </div>
                                            {seasons && seasons.length > 0 && (
                                                <div className={classes.statRow}>
                                                    <span className={classes.statLabel}>Stagioni</span>
                                                    <Typography className={classes.statValue}>{seasons.length}</Typography>
                                                </div>
                                            )}
                                            {parseFirstMatch(data.firstMatch) && (
                                                <div className={classes.statRow} style={{ alignItems: 'flex-start' }}>
                                                    <span className={classes.statLabel} style={{ paddingTop: 2 }}>
                                                        <StarIcon style={{ fontSize: 16, color: '#F0C040' }} /> Prima partita
                                                    </span>
                                                    <Box style={{ textAlign: 'right' }}>
                                                        <Typography style={{ fontSize: '0.82rem', fontWeight: 700, color: '#082D68' }}>
                                                            <Moment locale='it' format="LL">{parseFirstMatch(data.firstMatch)}</Moment>
                                                        </Typography>
                                                        {getFirstMatchGame(data.firstMatch) && (
                                                            <Typography style={{ fontSize: '0.72rem', color: 'rgba(0,0,0,0.5)', fontStyle: 'italic', marginTop: 1 }}>
                                                                {getFirstMatchGame(data.firstMatch)}
                                                            </Typography>
                                                        )}
                                                    </Box>
                                                </div>
                                            )}
                                        </Box>
                                    </Card>
                                </Grid>

                                {/* Mappa */}
                                {data.birthplace && <Grid item xs={12} sm={4} style={{ display: 'flex' }}>
                                    <Card elevation={1} style={{ flex: 1, overflow: 'hidden', padding: 0, minHeight: 220, display: 'flex', flexDirection: 'column' }}>
                                        {(data.birthplace || data.country) && (
                                            <Box style={{ padding: '8px 12px', borderBottom: '1px solid rgba(0,0,0,0.08)' }}>
                                                <Typography style={{ fontSize: '0.82rem', color: 'rgba(0,0,0,0.6)' }}>
                                                    {[data.birthplace, data.country].filter(Boolean).join(' · ')}
                                                </Typography>
                                            </Box>
                                        )}
                                        {mapLoading ? (
                                            <Box display="flex" alignItems="center" justifyContent="center" style={{ flex: 1 }} minHeight={180}>
                                                <CircularProgress size={24} />
                                            </Box>
                                        ) : coords ? (
                                            <iframe
                                                title="birthplace-map"
                                                width="100%"
                                                style={{ flex: 1, display: 'block', minHeight: 180, border: 0 }}
                                                frameBorder="0"
                                                scrolling="no"
                                                src={`https://www.openstreetmap.org/export/embed.html?bbox=${coords.lon - 0.8},${coords.lat - 0.6},${coords.lon + 0.8},${coords.lat + 0.6}&layer=mapnik&marker=${coords.lat},${coords.lon}`}
                                            />
                                        ) : (
                                            <Box display="flex" alignItems="center" justifyContent="center" style={{ flex: 1 }} minHeight={180}>
                                                <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.35)' }}>Posizione non disponibile</Typography>
                                            </Box>
                                        )}
                                    </Card>
                                </Grid>}
                            </Grid>

                            {/* Seasons table */}
                            <Typography className={classes.sectionLabel}>Stagioni</Typography>
                            <TableContainer component={Paper} elevation={0} style={{ border: '1px solid rgba(0,0,0,0.08)', borderRadius: 8 }}>
                                <Table size="small">
                                    <TableHead>
                                        <TableRow>
                                            <TableCell className={classes.header}>Anno</TableCell>
                                            <TableCell className={classes.header}>Serie</TableCell>
                                            <TableCell className={classes.header} align="center">Pres.</TableCell>
                                            <TableCell className={classes.header} align="center">Gol</TableCell>
                                            <TableCell className={classes.header} align="center">Amm.</TableCell>
                                            <TableCell className={classes.header} align="center">Esp.</TableCell>
                                        </TableRow>
                                    </TableHead>
                                    <TableBody>
                                        {seasons && seasons.length > 0 ? seasons.map((row) => (
                                            <TableRow key={row.year} className={classes.tableRow}>
                                                <TableCell className={classes.cell}>{row.year}</TableCell>
                                                <TableCell className={classes.cell}>
                                                    <MuiTooltip title={row.league} arrow><Avatar className={classes.avatarBlue}>{row.league}</Avatar></MuiTooltip>
                                                </TableCell>
                                                <TableCell className={classes.cell} align="center">
                                                    {parseInt(row.appareances) !== -1 && <MuiTooltip title="Presenze" arrow><Chip icon={<EventIcon style={{ fontSize: 12 }} />} label={row.appareances} size="small" color="primary" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700 }} /></MuiTooltip>}
                                                </TableCell>
                                                <TableCell className={classes.cell} align="center">
                                                    {parseInt(row.goal) !== -1 && <MuiTooltip title="Gol" arrow><Chip icon={<SportsSoccerIcon style={{ fontSize: 12 }} />} label={row.goal} size="small" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, backgroundColor: '#CA2331', color: '#fff' }} /></MuiTooltip>}
                                                </TableCell>
                                                <TableCell className={classes.cell} align="center">
                                                    {parseInt(row.yellowcard) !== -1 && <MuiTooltip title="Ammonizioni" arrow><Chip label={row.yellowcard} size="small" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, backgroundColor: '#FDDB3A', color: '#333' }} /></MuiTooltip>}
                                                </TableCell>
                                                <TableCell className={classes.cell} align="center">
                                                    {parseInt(row.redcard) !== -1 && <MuiTooltip title="Espulsioni" arrow><Chip label={row.redcard} size="small" style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, backgroundColor: '#CA2331', color: '#fff' }} /></MuiTooltip>}
                                                </TableCell>
                                            </TableRow>
                                        )) : (
                                            <TableRow>
                                                <TableCell colSpan={6} align="center">
                                                    <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.45)', padding: '8px 0' }}>Nessuna stagione disponibile</Typography>
                                                </TableCell>
                                            </TableRow>
                                        )}
                                    </TableBody>
                                </Table>
                            </TableContainer>

                            {seasons && seasons.length > 1 && (() => {
                                const chartData = [...seasons]
                                    .sort((a, b) => String(a.year).localeCompare(String(b.year)))
                                    .map(s => ({
                                        anno: s.year,
                                        Presenze: parseInt(s.appareances) !== -1 ? (parseInt(s.appareances) || 0) : 0,
                                        Gol: parseInt(s.goal) !== -1 ? (parseInt(s.goal) || 0) : 0,
                                    }));
                                return (
                                    <>
                                        <Typography className={classes.sectionLabel} style={{ marginTop: 16 }}>Andamento carriera</Typography>
                                        <ResponsiveContainer width="100%" height={200}>
                                            <BarChart data={chartData} margin={{ top: 4, right: 8, left: -20, bottom: 0 }}>
                                                <XAxis dataKey="anno" tick={{ fontSize: 10 }} interval="preserveStartEnd" />
                                                <YAxis tick={{ fontSize: 10 }} />
                                                <Tooltip contentStyle={{ fontSize: '0.75rem' }} />
                                                <Legend wrapperStyle={{ fontSize: '0.75rem' }} />
                                                <Bar dataKey="Presenze" fill="#082D68" radius={[3, 3, 0, 0]} />
                                                <Bar dataKey="Gol" fill="#CA2331" radius={[3, 3, 0, 0]} />
                                            </BarChart>
                                        </ResponsiveContainer>
                                    </>
                                );
                            })()}
                        </Box>
                        <Footer />
                    </>
                );
            })()}
        </Box>
    );
}
