const LEAGUE_CHIPS = [
  { slug: 'serie-A',   label: 'Serie A',         color: '#082D68' },
  { slug: 'serie-B',   label: 'Serie B',         color: '#CA2331' },
  { slug: 'serie-C1',  label: 'Serie C1',        color: '#E87722' },
  { slug: 'serie-1RS', label: 'Prima Divisione', color: '#6A0DAD' },
];

export default function SeasonList({ seasons, onSeasonSelect }) {
  const classes = useStyles();
  const navigate = useNavigate();
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(0);
  const rowsPerPage = 4;

  const handleChangePage = (event, newPage) => { setPage(newPage); };
  const handleQuery = (q) => { setQuery(q); setPage(0); };

  let filteredSeasons = seasons;
  if (query) {
    const searchMatch = new RegExp(escareRegExp(query), 'i');
    filteredSeasons = seasons.filter((season) => searchMatch.test(season.year));
  }
  filteredSeasons.sort(sortBy('-year'));

  return (
    <Card className={classes.root}>
      <CardHeader
        avatar={
          <Chip label="Stagioni" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
        }
        title="Cagliari Calcio"
        subheader="Seleziona una stagione"
      />
      <CardContent className={classes.content}>
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10, padding: '0 8px 10px', flexWrap: 'wrap' }}>
          <Typography className={classes.intro} style={{ padding: 0, flex: '1 1 160px' }}>
            <b>ArchivioRossoBlu</b> nasce dalla passione per il <b>Cagliari Calcio</b> e le <b>statistiche</b>. Dati dalla stagione <b>1947/1948</b> ad oggi.
          </Typography>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5, paddingTop: 2, flexShrink: 0 }}>
            {LEAGUE_CHIPS.map(({ slug, label, color }) => (
              <Chip
                key={slug}
                label={label}
                size="small"
                onClick={() => navigate(`/cagliari-calcio/stagioni/${slug}`)}
                style={{ backgroundColor: color, color: '#fff', fontWeight: 700, cursor: 'pointer' }}
              />
            ))}
          </div>
        </div>
        <div className={classes.searchBar}>
          <SportsSoccerIcon style={{ fontSize: '1rem', color: '#082D68', flexShrink: 0 }} />
          <InputBase
            placeholder="Cerca stagione…"
            className={classes.searchInput}
            inputProps={{ 'aria-label': 'cerca stagione' }}
            value={query}
            onChange={(e) => handleQuery(e.target.value)}
          />
        </div>
        <TableContainer>
          <Table stickyHeader size="small" aria-label="stagioni">
            <TableHead>
              <TableRow>
                <TableCell className={classes.header}>Serie</TableCell>
                <TableCell className={classes.header}>Anno</TableCell>
                <TableCell className={classes.header}>Punti</TableCell>
                <TableCell className={classes.header}>Pos.</TableCell>
                <TableCell className={classes.header}>V</TableCell>
                <TableCell className={classes.header}>P</TableCell>
                <TableCell className={classes.header}>S</TableCell>
                <TableCell className={classes.header}>GF</TableCell>
                <TableCell className={classes.header}>GS</TableCell>
                <TableCell className={classes.header}>DR</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {(rowsPerPage > 0
                ? filteredSeasons.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                : filteredSeasons
              ).map((row) => (
                <StyledTableRow key={row.id} onClick={() => onSeasonSelect(row.id, row.year)}>
                  <TableCell>
                    <Tooltip title={{ A: 'Serie A', B: 'Serie B', C1: 'Serie C1', '1RS': 'Prima divisione storica' }[row.league] ?? `Serie ${row.league}`} arrow>
                      <Avatar className={classes.avatar}>{row.league}</Avatar>
                    </Tooltip>
                  </TableCell>
                  <TableCell>
                    <Typography className={classes.yearLink}>{row.year}</Typography>
                  </TableCell>
                  <TableCell>
                    <Avatar className={classes.avatarBlue}>{row.points}</Avatar>
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2" color="textSecondary">
                      {row.position > 0 ? row.position : '—'}
                    </Typography>
                  </TableCell>
                  <TableCell><Typography variant="body2" color="textSecondary">{row.v}</Typography></TableCell>
                  <TableCell><Typography variant="body2" color="textSecondary">{row.d}</Typography></TableCell>
                  <TableCell><Typography variant="body2" color="textSecondary">{row.l}</Typography></TableCell>
                  <TableCell><Typography variant="body2" color="textSecondary">{row.gf}</Typography></TableCell>
                  <TableCell><Typography variant="body2" color="textSecondary">{row.gs}</Typography></TableCell>
                  <TableCell><Typography variant="body2" color="textSecondary">{row.dr}</Typography></TableCell>
                </StyledTableRow>
              ))}
            </TableBody>
            <TableFooter>
              <TableRow>
                <TablePagination
                  rowsPerPageOptions={[10]}
                  colSpan={10}
                  count={filteredSeasons.length}
                  rowsPerPage={rowsPerPage}
                  page={page}
                  slotProps={{ select: { inputProps: { 'aria-label': 'rows per page' }, native: true } }}
                  onPageChange={handleChangePage}
                  ActionsComponent={TablePaginationActions}
                />
              </TableRow>
            </TableFooter>
          </Table>
        </TableContainer>
      </CardContent>
    </Card>
  );
}
