import React, { useState } from 'react';
import { LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';
import { allSeasons } from '../../utils/generals';
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';
import Checkbox from '@mui/material/Checkbox';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import Chip from '@mui/material/Chip';
import { useTheme } from '@mui/material/styles';
import useMediaQuery from '@mui/material/useMediaQuery';
import { makeStyles } from '@mui/styles';
import SectionLabel from '../SectionLabel';

const useStyles = makeStyles(() => ({
  root: {
    borderTop: '4px solid #CA2331',
  },
  content: {
    padding: '0 8px 8px',
    '&:last-child': { paddingBottom: 8 },
  },
}));

const allChartData = allSeasons
  .filter(s => parseInt(s.position) > 0)
  .reverse()
  .map(s => ({
    year: s.year.slice(0, 4),
    fullYear: s.year,
    posizione: parseInt(s.position),
    campionato: s.league,
    punti: s.points,
    v: s.v,
    d: s.d,
    l: s.l,
    gf: s.gf,
    gs: s.gs,
  }));

const LEAGUE_COLOR = {
  'A':   '#082D68',
  'B':   '#CA2331',
  'C1':  '#E87722',
  '1RS': '#6A0DAD',
};

const CustomDot = (props) => {
  const { cx, cy, payload, isMobile } = props;
  const color = LEAGUE_COLOR[payload.campionato] || '#888';
  if (payload.fullYear === '1969/1970') {
    const r = isMobile ? 7 : 12;
    const fs = isMobile ? 9 : 16;
    const oy = isMobile ? 3 : 6;
    return (
      <g>
        <circle cx={cx} cy={cy} r={r} fill="#F0C040" stroke="#082D68" strokeWidth={1.5} />
        <text x={cx} y={cy + oy} textAnchor="middle" fontSize={fs}>🏆</text>
      </g>
    );
  }
  return <circle cx={cx} cy={cy} r={3} fill={color} stroke="#fff" strokeWidth={1} />;
};

const CustomTooltip = ({ active, payload }) => {
  if (!active || !payload || !payload.length) return null;
  const d = payload[0].payload;
  const color = LEAGUE_COLOR[d.campionato] || '#888';
  return (
    <Box style={{ background: '#fff', border: `1px solid ${color}`, borderRadius: 6, padding: '8px 12px', minWidth: 160 }}>
      <Typography style={{ fontWeight: 700, fontSize: '0.75rem', color, marginBottom: 4 }}>
        {d.fullYear} — Serie {d.campionato}
      </Typography>
      <Typography style={{ fontSize: '0.72rem', fontWeight: 700, marginBottom: 4 }}>{d.posizione}° posto · {d.punti} pt</Typography>
      <Box display="flex" gap={1.5}>
        <Box textAlign="center">
          <Typography style={{ fontSize: '0.65rem', color: '#4caf50', fontWeight: 700 }}>{d.v}</Typography>
          <Typography style={{ fontSize: '0.6rem', color: '#999' }}>V</Typography>
        </Box>
        <Box textAlign="center">
          <Typography style={{ fontSize: '0.65rem', color: '#888', fontWeight: 700 }}>{d.d}</Typography>
          <Typography style={{ fontSize: '0.6rem', color: '#999' }}>P</Typography>
        </Box>
        <Box textAlign="center">
          <Typography style={{ fontSize: '0.65rem', color: '#CA2331', fontWeight: 700 }}>{d.l}</Typography>
          <Typography style={{ fontSize: '0.6rem', color: '#999' }}>S</Typography>
        </Box>
      </Box>
      <Typography style={{ fontSize: '0.65rem', color: '#555', marginTop: 4 }}>
        Gol: <strong>{d.gf}</strong> fatti · <strong>{d.gs}</strong> subiti
      </Typography>
    </Box>
  );
};

const CustomXTick = ({ x, y, payload, index }) => {
  if (index % 5 !== 0) return null;
  return (
    <text x={x} y={y + 12} textAnchor="middle" fontSize={9} fill="#666">{payload.value}</text>
  );
};

const GoalsTooltip = ({ active, payload }) => {
  if (!active || !payload || !payload.length) return null;
  const d = payload[0].payload;
  const color = LEAGUE_COLOR[d.campionato] || '#888';
  return (
    <Box style={{ background: '#fff', border: `1px solid ${color}`, borderRadius: 6, padding: '8px 12px', minWidth: 140 }}>
      <Typography style={{ fontWeight: 700, fontSize: '0.75rem', color, marginBottom: 4 }}>
        {d.fullYear} — Serie {d.campionato}
      </Typography>
      <Box display="flex" gap={2}>
        <Box>
          <Typography style={{ fontSize: '0.65rem', color: '#4caf50', fontWeight: 700 }}>{d.gf}</Typography>
          <Typography style={{ fontSize: '0.6rem', color: '#999' }}>Fatti</Typography>
        </Box>
        <Box>
          <Typography style={{ fontSize: '0.65rem', color: '#CA2331', fontWeight: 700 }}>{d.gs}</Typography>
          <Typography style={{ fontSize: '0.6rem', color: '#999' }}>Subiti</Typography>
        </Box>
      </Box>
    </Box>
  );
};

export default function SeasonPositionChart() {
  const classes = useStyles();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const [selected, setSelected] = useState({ A: true, B: false, C1: false, '1RS': false });

  const toggle = (league) => setSelected(prev => {
    const next = { ...prev, [league]: !prev[league] };
    const anySelected = Object.values(next).some(Boolean);
    return anySelected ? next : prev;
  });

  const chartData = allChartData.filter(d => selected[d.campionato]);

  return (
    <Card className={classes.root}>
      <CardHeader
        avatar={<Chip label="Stagioni" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />}
        action={
          <Box display="flex" alignItems="center" gap={0.5} flexWrap="wrap" pr={1}>
            {Object.entries(LEAGUE_COLOR).map(([label, color]) => (
              <Box
                key={label}
                display="flex"
                alignItems="center"
                onClick={() => toggle(label)}
                style={{ cursor: 'pointer', userSelect: 'none' }}
              >
                <Checkbox
                  checked={selected[label]}
                  size="small"
                  style={{ color, padding: 2 }}
                />
                <Typography style={{ fontSize: '0.68rem', color: selected[label] ? color : '#aaa', fontWeight: selected[label] ? 700 : 400 }}>
                  {isMobile ? label : `Serie ${label}`}
                </Typography>
              </Box>
            ))}
          </Box>
        }
      />
      <CardContent className={classes.content}>
        <SectionLabel>Posizione in classifica</SectionLabel>
        <ResponsiveContainer width="100%" height={200}>
          <LineChart data={chartData} margin={{ top: 16, right: 8, left: -20, bottom: 0 }}>
            <XAxis dataKey="year" tick={<CustomXTick />} interval={0} />
            <YAxis
              reversed
              domain={[1, 22]}
              ticks={[1, 5, 10, 15, 20]}
              tick={{ fontSize: 9, fill: '#666' }}
              tickFormatter={v => `${v}°`}
            />
            <Tooltip content={<CustomTooltip />} />
            <ReferenceLine y={3} stroke="rgba(8,45,104,0.15)" strokeDasharray="4 2" />
            <ReferenceLine y={18} stroke="rgba(202,35,49,0.15)" strokeDasharray="4 2" />
            <Line
              type="monotone"
              dataKey="posizione"
              stroke="#082D68"
              strokeWidth={1.5}
              dot={(props) => <CustomDot {...props} isMobile={isMobile} />}
              activeDot={{ r: 5, fill: '#F0C040', stroke: '#082D68', strokeWidth: 2 }}
              isAnimationActive={true}
            />
          </LineChart>
        </ResponsiveContainer>
        <Box display="flex" alignItems="center" justifyContent="space-between" flexWrap="wrap" style={{ padding: '4px 4px 0' }}>
          <SectionLabel style={{ padding: 0 }}>Gol fatti / subiti</SectionLabel>
          <Box display="flex" alignItems="center" gap={1.5}>
            <Box display="flex" alignItems="center" gap={0.5}>
              <Box style={{ width: 16, height: 2, backgroundColor: '#4caf50', borderRadius: 1 }} />
              <Typography style={{ fontSize: '0.65rem', color: '#4caf50', fontWeight: 700 }}>Fatti</Typography>
            </Box>
            <Box display="flex" alignItems="center" gap={0.5}>
              <Box style={{ width: 16, height: 2, backgroundColor: '#CA2331', borderRadius: 1 }} />
              <Typography style={{ fontSize: '0.65rem', color: '#CA2331', fontWeight: 700 }}>Subiti</Typography>
            </Box>
          </Box>
        </Box>
        <ResponsiveContainer width="100%" height={180}>
          <LineChart data={chartData} margin={{ top: 8, right: 8, left: -20, bottom: 0 }}>
            <XAxis dataKey="year" tick={<CustomXTick />} interval={0} />
            <YAxis tick={{ fontSize: 9, fill: '#666' }} />
            <Tooltip content={<GoalsTooltip />} />
            <Line
              type="monotone"
              dataKey="gf"
              stroke="#4caf50"
              strokeWidth={1.5}
              dot={false}
              activeDot={{ r: 4 }}
              isAnimationActive={true}
            />
            <Line
              type="monotone"
              dataKey="gs"
              stroke="#CA2331"
              strokeWidth={1.5}
              dot={false}
              activeDot={{ r: 4 }}
              isAnimationActive={true}
            />
          </LineChart>
        </ResponsiveContainer>
      </CardContent>
    </Card>
  );
}
