// Parsing dei resoconti partita (HTML libero proveniente dall'archivio).
// Il testo arriva con markup misto: <br>, <div>, <p>, <span>, <b>...
// e con etichette non uniformi ("Marcatori:", "Gol:", "Reti:").

const BLOCK_CLOSE_RE = /<\/(?:div|p|li|tr|h[1-6]|blockquote)\s*>/gi;
const BR_RE = /<br\s*\/?>/gi;

const ENTITIES = {
  '&nbsp;': ' ',
  '&amp;': '&',
  '&lt;': '<',
  '&gt;': '>',
  '&quot;': '"',
  '&#39;': "'",
  '&apos;': "'",
};

const LABELS = {
  referee: /^(?:Arbitro|Arbitri|Direttore di gara)\s*:\s*(.*)$/i,
  scorers: /^(?:Marcatori|Marcatore|Gol|Goal|Reti|Rete)\s*:\s*(.*)$/i,
  bookings: /^(?:Ammoniti|Ammonito|Ammonizioni)\s*:\s*(.*)$/i,
  expulsions: /^(?:Espulsi|Espulso|Espulsioni)\s*:\s*(.*)$/i,
  notes: /^(?:Note|Annotazioni)\s*:\s*(.*)$/i,
};

// Riga dedicata all'allenatore ("All. Pisacane") o coda della formazione
// ("... El Bilal Toure. Allenatore: Cuesta").
const COACH_LINE_RE = /^(?:Allenatore|All\.?)\s*:?\s*(.+)$/i;
const COACH_INLINE_RE = /(?:^|[\s.;])(?:Allenatore|All\.)\s*:?\s*(.+)$/i;
// Righe che restano dentro il blocco di una squadra (riserve, sostituzioni).
const BENCH_RE = /^(?:A disposizione|In panchina|Panchina|Sostituzioni|Subentrati|Entrati)\s*:/i;

// Alcuni resoconti in archivio sono salvati con codifica doppia (UTF-8 letto
// come latin1): "19â€² pt" invece di "19′ pt". Se riconosciamo il pattern,
// ricostruiamo i byte originali e li rileggiamo come UTF-8.
// Byte 0x80-0x9F: caratteri che CP1252 mappa fuori dal range latin1.
const CP1252_BYTES = {
  '€': 0x80, '‚': 0x82, 'ƒ': 0x83, '„': 0x84, '…': 0x85,
  '†': 0x86, '‡': 0x87, 'ˆ': 0x88, '‰': 0x89, 'Š': 0x8A,
  '‹': 0x8B, 'Œ': 0x8C, 'Ž': 0x8E, '‘': 0x91, '’': 0x92,
  '“': 0x93, '”': 0x94, '•': 0x95, '–': 0x96, '—': 0x97,
  '˜': 0x98, '™': 0x99, 'š': 0x9A, '›': 0x9B, 'œ': 0x9C,
  'ž': 0x9E, 'Ÿ': 0x9F,
};

const MOJIBAKE_RE = new RegExp(
  '[\u00c2\u00c3\u00e2][\u0080-\u00bf\u2013\u2014\u2018\u2019\u201a'
  + '\u201c\u201d\u201e\u2020\u2021\u2022\u2026\u2030\u2039\u203a\u20ac\u2122]'
);

function fixMojibake(text) {
  if (!MOJIBAKE_RE.test(text)) return text;
  try {
    const bytes = Uint8Array.from(text, (ch) => {
      const code = ch.charCodeAt(0);
      if (code <= 255) return code;
      const mapped = CP1252_BYTES[ch];
      if (mapped === undefined) throw new Error('non ricostruibile');
      return mapped;
    });
    // fatal: se il risultato non è UTF-8 valido teniamo il testo originale.
    return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  } catch {
    return text;
  }
}

// Converte l'HTML del resoconto in righe di testo pulite.
export function reportToLines(html) {
  if (!html) return [];
  let text = fixMojibake(String(html))
    .replace(BR_RE, '\n')
    .replace(BLOCK_CLOSE_RE, '\n')
    .replace(/<[^>]+>/g, '');
  Object.entries(ENTITIES).forEach(([entity, char]) => {
    text = text.split(entity).join(char);
  });
  return text
    .replace(/\u00a0/g, ' ')
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map((line) => line.replace(/\s+/g, ' ').trim())
    .filter(Boolean);
}

// Divide un elenco su virgole e punti e virgola, ignorando quelli tra parentesi
// (es. "Rodriguez (66' Kofler), Obert").
export function splitList(value) {
  if (!value) return [];
  const items = [];
  let depth = 0;
  let cur = '';
  for (const ch of value) {
    if (ch === '(' || ch === '[') { depth += 1; cur += ch; }
    else if (ch === ')' || ch === ']') { depth = Math.max(0, depth - 1); cur += ch; }
    else if ((ch === ',' || ch === ';') && depth === 0) {
      const t = cur.trim();
      if (t) items.push(t);
      cur = '';
    } else cur += ch;
  }
  const last = cur.trim().replace(/\.$/, '').trim();
  if (last) items.push(last);
  return items;
}

function teamLineRegExp(teamName) {
  const escaped = teamName
    .trim()
    .replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    .replace(/[-\s]+/g, '[-\\s]+');
  // "Cagliari (4-3-2-1): Caprile; ..." oppure "CAGLIARI: Caprile, ..."
  return new RegExp(`^${escaped}\\s*(?:\\([^)]*\\))?\\s*:\\s*(.+)$`, 'i');
}

const cleanCoach = (value) => value.replace(/\.$/, '').trim();

// Riunisce le voci che iniziano con una parentesi al giocatore precedente:
// alcuni resoconti hanno una virgola di troppo ("Fazzini, (Fadera)").
function mergeStrayParens(items) {
  return items.reduce((acc, item) => {
    if (item.startsWith('(') && acc.length) acc[acc.length - 1] += ` ${item}`;
    else acc.push(item);
    return acc;
  }, []);
}

function extractLineup(lines, teamName) {
  const re = teamLineRegExp(teamName);
  const idx = lines.findIndex((line) => re.test(line));
  if (idx === -1) return {};

  let rest = lines[idx].match(re)[1];
  let coach = null;
  // L'allenatore può chiudere la riga della formazione...
  const inline = rest.match(COACH_INLINE_RE);
  if (inline) {
    coach = cleanCoach(inline[1]);
    rest = rest.slice(0, inline.index);
  }
  const players = mergeStrayParens(splitList(rest));
  if (!players.length) return {};
  // ...oppure stare poco sotto, eventualmente dopo le riserve. Ci fermiamo
  // appena incontriamo una riga che non appartiene più a questa squadra.
  for (let i = idx + 1; !coach && i < lines.length; i += 1) {
    const m = lines[i].match(COACH_LINE_RE);
    if (m) { coach = cleanCoach(m[1]); break; }
    if (!BENCH_RE.test(lines[i])) break;
  }
  return { players, coach };
}

// Estrae arbitro, marcatori, ammoniti, espulsi e formazioni dal resoconto.
export function parseMatchReport(html, home, away) {
  const lines = reportToLines(html);
  if (!lines.length) return {};

  const result = {};
  Object.entries(LABELS).forEach(([key, re]) => {
    const line = lines.find((l) => re.test(l));
    if (!line) return;
    const value = line.match(re)[1].trim();
    if (value && value !== '-') result[key] = value;
  });

  if (home) {
    const { players, coach } = extractLineup(lines, home);
    if (players?.length) { result.homeLineup = players; result.homeCoach = coach; }
  }
  if (away) {
    const { players, coach } = extractLineup(lines, away);
    if (players?.length) { result.awayLineup = players; result.awayCoach = coach; }
  }

  return result;
}
