import React, { useState, useEffect } from 'react';
import { makeStyles } from '@mui/styles';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import CardActions from '@mui/material/CardActions';
import Typography from '@mui/material/Typography';
import Chip from '@mui/material/Chip';
import Divider from '@mui/material/Divider';
import Skeleton from '@mui/material/Skeleton';
import OpenInNewIcon from '@mui/icons-material/OpenInNew';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import { trackCardClick } from '../../utils/analytics';
import IconButton from '@mui/material/IconButton';
import Button from '@mui/material/Button';
import Avatar from '@mui/material/Avatar';
import NewspaperIcon from '@mui/icons-material/Newspaper';

const FEEDS = [
  { url: 'https://www.tuttocagliari.net/rss/?section=3', label: 'TuttoCagliari' },
  { url: 'https://www.corrieredellosport.it/rss/calcio/serie-a/cagliari', label: 'CdS' },
  { url: 'https://www.gazzetta.it/dynamic-feed/rss/section/Calcio.xml', label: 'Gazzetta', filter: 'Cagliari' },
  { url: 'https://www.transfermarkt.it/rss/news', label: 'Transfermarkt', filter: 'Cagliari' },
  { url: 'https://www.tuttosport.com/rss/calcio/serie-a/cagliari', label: 'Tuttosport' },
];

const RSS2JSON = 'https://api.rss2json.com/v1/api.json?rss_url=';

async function fetchReddit() {
  try {
    const res = await fetch(
      'https://www.reddit.com/r/calcio/search.json?q=Cagliari&sort=new&limit=10&restrict_sr=1',
      { headers: { 'Accept': 'application/json' } }
    );
    const json = await res.json();
    return (json?.data?.children ?? []).map(({ data: p }) => ({
      title: p.title,
      link: `https://www.reddit.com${p.permalink}`,
      date: new Date(p.created_utc * 1000).toISOString(),
      thumbnail: p.thumbnail?.startsWith('http') ? p.thumbnail : null,
      source: 'r/calcio',
      score: p.score,
    }));
  } catch {
    return [];
  }
}

const useStyles = makeStyles((theme) => ({
  root: {
    borderTop: '4px solid #CA2331',
  },
  content: {
    overflowY: 'auto',
    maxHeight: 520,
    padding: theme.spacing(0, 1),
    '&:last-child': { paddingBottom: theme.spacing(1) },
  },
  grid: {
    display: 'grid',
    gridTemplateColumns: '1fr',
    gap: theme.spacing(0.5),
  },
  item: {
    display: 'flex',
    alignItems: 'flex-start',
    gap: theme.spacing(1),
    padding: theme.spacing(0.8, 1),
    borderRadius: 6,
    cursor: 'pointer',
    textDecoration: 'none',
    color: 'inherit',
    '&:hover': {
      backgroundColor: theme.palette.action.hover,
    },
  },
  thumb: {
    width: 56,
    height: 56,
    borderRadius: 6,
    objectFit: 'cover',
    flexShrink: 0,
    backgroundColor: 'rgba(0,0,0,0.06)',
  },
  title: {
    fontSize: '0.78rem',
    fontWeight: 600,
    lineHeight: 1.4,
    display: '-webkit-box',
    '-webkit-line-clamp': 2,
    '-webkit-box-orient': 'vertical',
    overflow: 'hidden',
  },
  meta: {
    fontSize: '0.68rem',
    color: 'rgba(0,0,0,0.45)',
    marginTop: 2,
  },
}));

async function fetchFeed(feed) {
  const res = await fetch(`${RSS2JSON}${encodeURIComponent(feed.url)}&count=10`);
  const json = await res.json();
  if (json.status !== 'ok') return [];
  return (json.items || [])
    .filter(item => !feed.filter || item.title?.includes(feed.filter))
    .map(item => ({
      title: item.title,
      link: item.link,
      date: item.pubDate,
      thumbnail: item.thumbnail || item.enclosure?.link || null,
      source: feed.label,
    }));
}

export default function NewsCard({ compact = false }) {
  const classes = useStyles();
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [updatedAt, setUpdatedAt] = useState(null);

  const limit = compact ? 5 : 20;

  useEffect(() => {
    Promise.all([
      ...FEEDS.map(f => fetchFeed(f).catch(() => [])),
      fetchReddit(),
    ])
      .then(results => {
        const cutoff = Date.now() - 7 * 24 * 60 * 60 * 1000;
        const merged = results.flat()
          .filter(item => new Date(item.date).getTime() >= cutoff)
          .sort((a, b) => new Date(b.date) - new Date(a.date))
          .slice(0, limit);
        setItems(merged);
        setUpdatedAt(new Date());
      })
      .finally(() => setLoading(false));
  }, [limit]);

  return (
    <Card className={classes.root}>
      <CardHeader
        avatar={
          <Chip
            label="News"
            size="small"
            style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }}
          />
        }
        title="Ultime notizie"
        subheader={updatedAt
          ? `Aggiornato alle ${updatedAt.toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' })}`
          : 'Cagliari Calcio'
        }
      />
      <Divider />
      <CardContent className={classes.content}>
        {loading ? (
          <div className={classes.grid}>
            {Array.from({ length: 6 }).map((_, i) => (
              <Skeleton key={i} variant="rectangular" height={72} style={{ borderRadius: 6, margin: '4px 0' }} />
            ))}
          </div>
        ) : (
          <div className={classes.grid}>
            {items.map((item, i) => (
              <a key={i} href={item.link} target="_blank" rel="noopener noreferrer" className={classes.item} onClick={() => trackCardClick(`news_${item.source.toLowerCase().replace(/[^a-z0-9]/g, '_')}`)}>
                {item.thumbnail ? (
                  <img src={item.thumbnail} alt="" className={classes.thumb} />
                ) : item.source === 'r/calcio' ? (
                  <Avatar style={{ width: 56, height: 56, borderRadius: 6, backgroundColor: '#FF4500', flexShrink: 0, fontSize: '0.65rem', fontWeight: 700 }}>
                    Reddit
                  </Avatar>
                ) : (
                  <Avatar style={{ width: 56, height: 56, borderRadius: 6, backgroundColor: '#082D68', flexShrink: 0 }}>
                    <NewspaperIcon />
                  </Avatar>
                )}
                <div style={{ flex: 1, minWidth: 0 }}>
                  <Typography className={classes.title}>{item.title}</Typography>
                  <Typography className={classes.meta}>
                    {item.source} · {new Date(item.date).toLocaleDateString('it-IT', { day: '2-digit', month: '2-digit', year: 'numeric' })}
                  </Typography>
                </div>
                <IconButton size="small" style={{ padding: 2, flexShrink: 0 }}>
                  <OpenInNewIcon style={{ fontSize: 14 }} />
                </IconButton>
              </a>
            ))}
          </div>
        )}
      </CardContent>
      {compact && (
        <>
          <Divider />
          <CardActions style={{ justifyContent: 'flex-end', padding: '4px 8px' }}>
            <Button
              component="a"
              href="/cagliari-calcio/news"
              size="small"
              endIcon={<ArrowForwardIcon />}
              style={{ color: '#082D68', fontWeight: 600, fontSize: '0.72rem' }}
            >
              Tutte le news
            </Button>
          </CardActions>
        </>
      )}
    </Card>
  );
}
